puts "Creating countries..."
c = ISO3166::Country.all
c.each do |country|
  Country.create!({
      short_name: country.alpha2,
      long_name: country.translations[:fr]
    })
  end
Country.all.each do |country|
  country.update!({ flag:  country.country_flag(country.short_name) })
end

