Record.create!({ original_title: "The Wrong Trousers", french_title: "Un mauvais pantalon", length_in_mn: 30, year: 1993, is_recorded: true, is_seen: false, is_available: true, abstract: "Afin de pouvoir payer toutes ses factures, Wallace décide de louer une des chambres de sa maison. Le nouveau locataire, un étrange pingouin, va rapidement troubler la vie de Wallace, l'inventeur, et de son fidèle chien, Gromit.", rank: nil, language_version_id: 1, medium_ids:[1] })
