Record.create!({ original_title: "Alexander", french_title: "Alexandre", length_in_mn: 175, year: 2004, is_recorded: true, is_seen: false, is_available: true, abstract: "La vie d'Alexandre le Grand, narrée par Ptolémée : de son enfance à sa mort, des cours d'Aristote aux conquêtes qui firent sa légende, de l'intimité aux champs de bataille. Fils du roi Philippe II, il soumit la Grèce révoltée, fonda Alexandrie, défit les Perses, s'empara de Babylone et atteint l'Indus pour établir à 32 ans l'un des plus grands empires ayant jamais existé.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Ben-Hur", french_title: "Ben-Hur", length_in_mn: 125, year: 2016, is_recorded: true, is_seen: false, is_available: true, abstract: "Ben-Hur retrace l’histoire épique de Judah Ben-Hur, un prince accusé à tort de trahison par Messala, son frère adoptif, officier de l’armée romaine. Déchu de son titre, séparé de sa famille et de la femme qu’il aime, Judah est réduit à l’esclavage. Après des années en mer, Judah revient sur sa terre natale dans le but de se venger. Il va y rencontrer son destin.", rank: nil, language_version_id: 1, medium_ids:[1] })
