Record.create!({ original_title: "", french_title: "Antigang", length_in_mn: 89, year: 2015, is_recorded: true, is_seen: true, is_available: false, abstract: "Serge Buren, flic légendaire de la BRI parisienne, et son équipe de jeunes policiers aux méthodes peu orthodoxes, sont aux prises avec un groupe de braqueurs violents et expéditifs quant aux méthodes utilisées pour commettre leurs méfaits, n'hésitant pas à se servir d'armes de guerre et de bombes pour dévaliser bijouteries et banques. Face à de tels ennemis, les policiers devront user d'ingéniosité pour les arrêter avant qu'ils ne fassent plus de victimes.", rank: 1, language_version_id: 1, medium_ids:[1] })
