Record.create!({ original_title: "", french_title: "Puzzle", length_in_mn: 90, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Dans la petite ville de Doulac, un mystérieux corbeau vient perturber les habitants par des révélations sur un meurtre non élucidé ayant eu lieu quelques années plus tôt. Alors que le meurtrier tente de protéger son secret, le juge Thomas Aubert revient en ville prêt à enfin élucider cette affaire.", rank: nil, language_version_id: 1, medium_ids:[1] })
