Record.create!({ original_title: "", french_title: "Quand vient la peur, partie 1", length_in_mn: 85, year: 2010, is_recorded: true, is_seen: false, is_available: true, abstract: "Au début des années 1970, à Châtelaillon, une série de crimes sanglants a pour cible des femmes brunes. La police, qui ne croit pas en l'existence d'un tueur en série, piétine et se montre impuissante à mener l'enquête. Les meurtres se multiplient et les femmes se teignent toutes en blond. La peur, l'irrationnel et la folie finissent par s'installer pour de bon.", rank: nil, language_version_id: 1, medium_ids:[1] })
