Record.create!({ original_title: "Elysium", french_title: "Elysium", length_in_mn: 105, year: 2013, is_recorded: true, is_seen: true, is_available: false, abstract: "Au XXIIe siècle, la population humaine riche vit désormais dans une station spatiale baptisée Elysium. Un ouvrier qui a été gravement irradié apprend qu'il ne lui reste plus que quelques jours à vivre. Il met à profit ce court laps de temps pour tenter de se rendre sur Elysium, car des cabines médicales y ont été installées, permettant la guérison de toutes les maladies recensées.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Ex machina", french_title: "Ex machina", length_in_mn: 108, year: 2014, is_recorded: true, is_seen: true, is_available: false, abstract: "Caleb, 26 ans, est programmeur dans l’une des plus importantes entreprises d’informatique au monde. Il gagne un concours interne pour passer une semaine dans un lieu retiré en montagne appartenant à Nathan, le PDG solitaire de son entreprise qui jouit de sa fortune gagnée grâce à un moteur de recherche révolutionnaire.", rank: nil, language_version_id: 1, medium_ids:[1] })
