Record.create!({ original_title: "The Charge of the Light Brigade", french_title: "La charge de la brigade légère", length_in_mn: 115, year: 1936, is_recorded: true, is_seen: true, is_available: false, abstract: "Suite à l'imminence d'un conflit impliquant notamment l'Angleterre et la Russie, un officier des Indes est chargé de partir en Arabie pour fournir l'armée en chevaux. Alors qu'il s'arrête à Calcutta pour voir sa fiancée, la garnison est attaquée par le sultan Surat Khan, nouvel allié des Russes.", rank: nil, language_version_id: 1, medium_ids:[1] })
