Record.create!({ original_title: "", french_title: "Tandem", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "Le commandant Léa Soler est mutée dans la brigade du capitaine Paul Marchal, son ex-mari, et ils vont tant bien que mal devoir faire équipe. Ils seront aussi obligés de se croiser en dehors du travail car le tandem a deux adolescents à gérer, Alice et Thomas.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 1", length_in_mn: nil, year: 2016, is_recorded: false, is_seen: false, is_available: true, abstract: "0", rank: 1, language_version_id: 1, medium_ids:[1] })
