Record.create!({ original_title: "", french_title: "Le Saut de l'ange (pilote)", length_in_mn: 90, year: 2015, is_recorded: false, is_seen: false, is_available: true, abstract: "Le Commissaire Cassandre est en lice pour prendre la tête du 36 mais elle demande sa mutation pour Annecy afin de s'occuper de son fils Jules. Tout en faisant connaissance avec sa nouvelle équipe, elle enquête sur la mort d'une auxiliaire de vie.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "L'École est finie", length_in_mn: 90, year: 2016, is_recorded: true, is_seen: false, is_available: true, abstract: "Gaëlle Servaz, éducatrice dans un lycée pour jeunes en difficulté est retrouvée morte chez elle.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Neiges éternelles", length_in_mn: 90, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Lors d'une randonnée, un couple est abattu. Leur fille est retrouvée blessée.", rank: 3, language_version_id: 1, medium_ids:[1] })
