Record.create!({ original_title: "", french_title: "Retour de flamme", length_in_mn: 90, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Le maire du village d'Annecy-le-Vieux est retrouvé mort au pied du château en cours de restauration.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le Pacte", length_in_mn: 90, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Le cadavre de maître Thomas Valin, avocat d'un important laboratoire de biogénétique, est repêché dans un canal de la ville.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "À contre-courant", length_in_mn: 90, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Lors d'un transfer, deux prisonnières s'évadent en tirant sur un gendarme.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le Valet noir", length_in_mn: 90, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Un jeune médecin est retrouvé mort dans sa voiture, suspendue à un piton rocheux.", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Fausse note", length_in_mn: 90, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Un cadavre est découvert lors d'une partie d'airsoft. Il s'agit de Lucas Marceau, infirmier à la clinique des Cimes. L'enquête s'oriente bientôt vers un élève de sa femme Magalie Marceau, jeune professeure de piano ː le jeune David Lemoine, 16 ans, musicien prodige à l'école Chopin, qui est aussi l'élève du célèbre, et terrible, professeur Triberg.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Mort blanche", length_in_mn: 90, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Une jeune étudiante meurt d'une overdose sur un chemin de randonnée.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Sans condition", length_in_mn: 90, year: 2018, is_recorded: false, is_seen: false, is_available: true, abstract: "Un collègue de Philippe Cassandre est retrouvé mort dans un camion de contrebande.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le loup gris", length_in_mn: 90, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Un chasseur, ancien militaire, est abattu en pleine forêt.", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Une vie meilleure", length_in_mn: 90, year: 2019, is_recorded: false, is_seen: false, is_available: true, abstract: "Un homme ceinturé d'explosifs surgit en pleine plaidoirie d'Évelyne Roche", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Secret assassin", length_in_mn: 90, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Lola Perrin, 25 ans, est retrouvée morte dans un hangar à bateaux au même endroit qu'Alice Bellanger, dix ans plus tôt. L'assassin de cette dernière, Victor Sénac, vient de sortir de prison.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "La Rançon du silence", length_in_mn: 90, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Un homme de 25 ans est retrouvé assassiné. Un homme inconscient gît à ses côtés, l'arme du crime à la main. A son réveil, non seulement il ne se souvient de rien, mais il connaissait à peine la victime et n'a aucun mobile apparent.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Pain béni", length_in_mn: 90, year: 2020, is_recorded: true, is_seen: false, is_available: true, abstract: "Le corps d'un boulanger est retrouvé dans le puits d'un monastère.", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Temps mort", length_in_mn: 90, year: 2020, is_recorded: true, is_seen: false, is_available: true, abstract: "Un corps est retrouvé dans la propriété d'une célèbre famille d'Annecy spécialisée dans l'horlogerie de luxe mais lorsque Cassandre arrive le corps a disparu.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Nature blessée", length_in_mn: 90, year: 2020, is_recorded: false, is_seen: false, is_available: true, abstract: "Un homme sans identité est retrouvé inconscient dans un torrent.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Les compagnons", length_in_mn: 90, year: 2021, is_recorded: true, is_seen: false, is_available: true, abstract: "Lors d'une journée portes ouvertes dans le centre d’hébergement et de travail « La première pierre », la directrice y est retrouvée assassinée.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le Secret d'Angèle", length_in_mn: 90, year: 2021, is_recorded: false, is_seen: false, is_available: true, abstract: "Le corps sans vie d'une jeune lycéenne en internat est retrouvé dans un cimetière. Comment Angèle a-t-elle pu se retrouver là?", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 6", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 1", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Die Superkräfte der Tiere", french_title: "La médecine face aux superpouvoirs des animaux", length_in_mn: 53, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Transposées à l’homme, les capacités étonnantes de certaines espèces animales pourraient sauver de nombreuses vies. Décryptage de ces superpouvoirs et de leurs promesses.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Stratégies de reproduction : les clés du succès", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "Qu'est-ce qui permet à certaines espèces de survivre dans des conditions difficiles ? Quels sont les secrets de leur évolution et de leur longévité ? En deux épisodes, cette minisérie capture des comportements animaliers en Amérique du Sud, en Indonésie, en Chine, au Japon, en Russie ou en Corée du Sud.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le cycle sans fin de la sélection naturelle", length_in_mn: 45, year: 2017, is_recorded: true, is_seen: true, is_available: true, abstract: "Ce premier épisode montre les stratégies des crapauds du Suriname, dont les femelles portent leurs œufs sur leur dos pendant 80 jours, mais aussi celles des éphémères, qui, pour échapper à leurs prédateurs, s'accouplent dans les airs, ou des araignées-loups, qui se laissent dévorer par leurs bébés.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "La guerre secrète", length_in_mn: 42, year: 2021, is_recorded: true, is_seen: true, is_available: true, abstract: "Ce second épisode débute avec le rituel complexe de la parade nuptiale des oiseaux de paradis, avant de s’intéresser aux saumons, qui remontent des milliers de kilomètres à contre-courant pour frayer dans leur lieu de naissance. Gros plan ensuite sur la reproduction asexuée des pucerons, les stratégies insolites des poissons-mandarins pour échapper à leurs prédateurs ou encore les mœurs des libellules qui peuplent nos points d’eau. Documentaire de Park Seo-ung et Heo Chan-seok.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 1", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Necklace", french_title: "Quoi de neuf docteur ?", length_in_mn: 42, year: 2016, is_recorded: false, is_seen: false, is_available: true, abstract: "Le docteur Jason Bull est un psychologue et consultant juridique, il s'est spécialisé dans la préparation des témoins en utilisant ses compétences et sa technologie pour déduire les intentions des jurés, de son client et de toutes les personnes impliquées. Il est embauché pour aider à défendre le fils d'un millionnaire accusé d'avoir couché avec une dealeuse de son école et de l'avoir assassinée.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Woman in 8D", french_title: "La Théorie du genre", length_in_mn: 42, year: 2016, is_recorded: false, is_seen: false, is_available: true, abstract: "Un accident d'avion de ligne cause la mort de 62 personnes, seul le pilote de l'avion, le capitaine Taylor Mathison, survit au crash. Pour éviter la publicité négative, la compagnie aérienne souhaite passer un accord pour négligence contre Mathison. Si elle accepte, elle ne pourra plus jamais être pilote de ligne. Bull prend en charge sa défense, en mettant en avant le fait que si elle avait été un homme, elle aurait été plus facilement acquittée.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Unambiguous", french_title: "Le Quatrième Pouvoir", length_in_mn: 42, year: 2016, is_recorded: false, is_seen: false, is_available: true, abstract: "Un basketteur universitaire est assassiné. Une blogueuse populaire révèle au grand public qu'une camarade, Reese, l'avait accusé de l'avoir violée quelque temps plus tôt. Tout porte à croire que Reese s'est vengée. L'équipe de Bull s'occupe de l'affaire et essaye d'insuffler le doute dans l'esprit des jurés.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Calisto", french_title: "Callisto", length_in_mn: 42, year: 2016, is_recorded: false, is_seen: false, is_available: true, abstract: "Une jeune biologiste a développé un traitement contre l’hémophilie pour soigner sa sœur et le met sur le marché. Mais une entreprise pharmaceutique, menée par Errol Windemere, qui détient le brevet du traitement original. L'équipe de Bull se rend à Callisto au Texas pour la défendre. Malheureusement, ce ne sera pas facile, car le plaignant, défendu par la belle Diana Lindsay, a le système judiciaire dans sa poche, d'autant plus que Bull y a connu sa seule défaite il y a quelques années.", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Just Tell the Truth", french_title: "Rien que la vérité", length_in_mn: 42, year: 2016, is_recorded: false, is_seen: false, is_available: true, abstract: "Les parents d'une femme victime de meurtre veut engager Bull pour les défendre au procès contre le suspect, son compagnon Richard. Mais le psychiatre décide de défendre ce dernier, et critiquera l'interrogatoire qu'il a subi.", rank: 5, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Bedside Manner", french_title: "Les Dieux de l'Olympe", length_in_mn: 42, year: 2016, is_recorded: false, is_seen: false, is_available: true, abstract: "Une femme décide d'attaquer son chirurgien Terrence Robeson (Tom Lipinski) qui l'a rendu stérile dû à des complications dans une opération. L'équipe du docteur Bull décide de défendre ce dernier, ce qui ne sera pas si facile à cause de son caractère. Pour cela, il faut sélectionner des jurés pragmatiques.", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Never Saw the Sign", french_title: "Collision", length_in_mn: 42, year: 2016, is_recorded: false, is_seen: false, is_available: true, abstract: "Un juge demande au docteur Bull de prendre en charge la défense d'un homme qui vient de perdre sa femme dans un accident. En effet, le procureur l'attaque en justice pour homicide involontaire, ce qui est rare d'habitude. Bull comprend très vite que c'est le député Dormit qui est derrière tout cela.", rank: 7, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Too Perfect", french_title: "Madame Parfaite", length_in_mn: 42, year: 2016, is_recorded: false, is_seen: false, is_available: true, abstract: "L'équipe prend en charge l'ex-femme de Bull et sœur de Benny, Izabella Colon, qui est à la tête d'une entreprise de conseils minceurs. Cette dernière est attaquée en justice après la mort suspecte d'une adepte.", rank: 8, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Light My Fire", french_title: "Rumeurs et préjugés", length_in_mn: 42, year: 2016, is_recorded: false, is_seen: false, is_available: true, abstract: "Dans la petite ville de Kavanaugh dans le New Hampshire, pas si tranquille en évidence, le docteur Bull s'occupe de défendre un jeune homme, victime de rumeurs depuis de nombreuses années, suspecté de meurtre et pyromanie. Il en profite pour faire la leçon aux habitants des effets des rumeurs.", rank: 9, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "E. J.", french_title: "E. J.", length_in_mn: 42, year: 2017, is_recorded: false, is_seen: false, is_available: true, abstract: "Une femme surdouée à la tête d'une entreprise de voiture conduite par ordinateur (""E. J."") fait appel aux services de Bull après la mort d'un de ses employés tué par un de ces véhicules.", rank: 10, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Teacher's Pet", french_title: "La Mante religieuse", length_in_mn: 42, year: 2017, is_recorded: false, is_seen: false, is_available: true, abstract: "Les services du docteur Bull sont requis après qu'une liaison entre un jeune lycéen et sa professeure d'anglais a été révélée.", rank: 11, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Stockholm Syndrome", french_title: "Le Syndrome de Stockholm", length_in_mn: 42, year: 2017, is_recorded: false, is_seen: false, is_available: true, abstract: "Une jurée ""miroir"" prend en otage le cabinet de Bull pendant une étude de procès. Elle lui demande de prouver l'innocence de son mari, déclaré coupable et emprisonné depuis trois ans.", rank: 12, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Fall", french_title: "La Chute des Titans", length_in_mn: 42, year: 2017, is_recorded: false, is_seen: false, is_available: true, abstract: "Un compétiteur de e-sport est accusé de tricherie après avoir fait perdre son équipe. Bull décide de le défendre.", rank: 13, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "It's Classified", french_title: "Secret défense", length_in_mn: 42, year: 2017, is_recorded: false, is_seen: false, is_available: true, abstract: "L'équipe de Bull défend tant bien que mal une militaire coupable de fuite de documents classés secret défense.", rank: 14, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "What's Your Number?", french_title: "Le Milliardaire sociopathe", length_in_mn: 42, year: 2017, is_recorded: false, is_seen: false, is_available: true, abstract: "Après la chute d'une passerelle tuant 15 personnes, un substitut procureur fait appel à l'équipe de Bull pour attaquer Andrew Withrow, un milliardaire promoteur immobilier, pour homicide involontaire. Mais ce dernier, qualifié de sociopathe par le psychiatre, a fait venir Diana Lindsay de Callisto pour le défendre, et met beaucoup de bâtons dans les roues de l'équipe.", rank: 15, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Name Game", french_title: "Les Loups de Wall Street", length_in_mn: 42, year: 2017, is_recorded: false, is_seen: false, is_available: true, abstract: "Une institutrice perd toutes ses économies après avoir suivi une offre d'investissement de la banque dans laquelle Dr Bull a aussi son compte. Ce dernier associe toutes les autres victimes que la banque a faites pour intenter une action collective. Les dépenses associées sont telles que son entreprise se retrouve en jeu si jamais il ne gagne pas le procès. Benny nuit à l'affaire en étant incapable de contrôler son attirance envers l'institutrice et son angoisse vis-à-vis du secret qu'il garde.", rank: 17, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Dressed to Kill", french_title: "Victime de la mode", length_in_mn: 42, year: 2017, is_recorded: false, is_seen: false, is_available: true, abstract: "Nella Wester, la mentor de Chunck, lorsque ce dernier travaillait encore dans le domaine de la mode, est assassinée, la robe qu'elle portait à la fin du défilé ayant été empoisonnée. Son nouveau protégé est accusé du meurtre, mais Dr Bull choisit de le défendre, contre l'avis de Chunk, persuadé de sa culpabilité.", rank: 18, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Bring It On", french_title: "Guerre d'egos", length_in_mn: 42, year: 2017, is_recorded: false, is_seen: false, is_available: true, abstract: "Dr Bull défend un avocat à l'ego surdimensionné, Jules Caffrey, accusé d'avoir tué sa compagne en la noyant dans la baignoire.", rank: 19, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Make Me", french_title: "Meurtre sous hypnose", length_in_mn: 42, year: 2017, is_recorded: false, is_seen: false, is_available: true, abstract: "Le Dr Bull défend un jeune étudiant, Troy Dickerson, accusé d'avoir tué son père. Il est persuadé que ce dernier a été poussé à le faire suite à des séances d'hypnose prodiguées par la Lumansic Academy. Chunk et Danny se rendent sous couverture dans cette simili-secte, pour essayer de découvrir comment sont ""reprogrammés"" leurs membres. Benny finit par se confier au Dr Bull sur ce qui le tracasse.", rank: 20, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "How to Dodge a Bullet", french_title: "En pleine tempête", length_in_mn: 42, year: 2017, is_recorded: false, is_seen: false, is_available: true, abstract: "Benny Colon est arrêté pour avoir envoyé un homme en prison, après la découverte de nouvelles preuves. Bull doit engager l'avocate J.P. Nunnelly pour réussir à lui éviter la prison. Cette dernière acceptera à condition que Bull vienne l'aider à plaider dans trois affaires.", rank: 21, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Dirty Little Secrets", french_title: "Nos vilains petits secrets", length_in_mn: 42, year: 2017, is_recorded: false, is_seen: false, is_available: true, abstract: "J. P. Nunnelly fait appel à Bull dans le cadre de son marché dans l’épisode précédent afin de défendre son client, un PDG d'une entreprise de sécurité, qui refuse de donner au FBI la liste de leurs clients après l'explosion d'un immeuble. L'équipe (Bull compris) accepte avec déplaisir. Mais ce sera sans Cable, concernée indirectement par l'explosion...", rank: 22, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Benevolent Deception", french_title: "Miami vice", length_in_mn: 42, year: 2017, is_recorded: false, is_seen: false, is_available: true, abstract: "J. P. et Bull se rendent en Floride pour défendre une femme accusée d'un trafic de drogue auquel le frère semble être mêlé.", rank: 23, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "School for Scandal", french_title: "La Veuve noire", length_in_mn: 42, year: 2017, is_recorded: false, is_seen: false, is_available: true, abstract: "0", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Already Gone", french_title: "Plutôt mourir", length_in_mn: 42, year: 2017, is_recorded: false, is_seen: false, is_available: true, abstract: "0", rank: 2, language_version_id: 1, medium_ids:[1] })
