Record.create!({ original_title: "", french_title: "Saison 3", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Haunted House", french_title: "La maison hantée", length_in_mn: 45, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Agatha ouvre sa propre agence de détective mais les clients potentiels ne sont pas légion. A la recherche de nouvelles affaires, Agatha et James visitent Ivy Hall, une maison soi-disant hantée depuis la guerre civile anglaise. Les bruits étranges la nuit et les pas inexpliqués sont-ils réellement surnaturels ou quelqu’un essaye-t-il de faire fuir la propriétaire de la maison ?", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Deadly Dance", french_title: "La danse fatale", length_in_mn: 45, year: 2020, is_recorded: true, is_seen: false, is_available: true, abstract: "Agatha ouvre sa propre agence de détective mais les clients potentiels ne sont pas légion. A la recherche de nouvelles affaires, Agatha et James visitent Ivy Hall, une maison soi-disant hantée depuis la guerre civile anglaise. Les bruits étranges la nuit et les pas inexpliqués sont-ils réellement surnaturels ou quelqu’un essaye-t-il de faire fuir la propriétaire de la maison ?", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Love from Hell", french_title: "L'enfer de l'amour", length_in_mn: 45, year: 2020, is_recorded: false, is_seen: false, is_available: true, abstract: "La relation entre Agatha Raisin et James Lacey va mal. Un meurtre prend place à la suite d’une dispute en public et James disparaît.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "And the pig that turned", french_title: "Du lard ou du cochon", length_in_mn: 45, year: 2020, is_recorded: false, is_seen: false, is_available: true, abstract: "Agatha est engagée par la femme d’un officier de police du village de Winter Parva afin d’enquêter sur son terrible meurtre.", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Wizard of Evesham", french_title: "Le magicien des ciseaux", length_in_mn: 45, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Le tout Evesham se presse chez le nouveau coiffeur de ces dames : Jonny Shawpart. Agatha tombe bientôt sous son charme. Mais elle découvre vite que Jonny Shawpart est à un stade bien plus avancé avec deux autres clientes, Liza Friendly et Maggie Henderson, qu'il a séduites puis fait chanter. Il partage avec elles de lourds secrets. Agatha enquête sur Jonny avec l'aide de Roy, Gemma et de Sarah.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Luther", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "Théo Luther est le plus redoutable chef de groupe de la Brigade Criminelle de Paris. Après avoir traqué un tueur d’enfants pendant de longs mois, il fait une dépression et met son mariage en péril. Aujourd’hui, réintégré dans son unité, Théo est sous surveillance. Pour être pleinement réhabilité, il va devoir vaincre tant ses démons intimes que les criminels.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 1", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Démons ordinaires", length_in_mn: 52, year: 2021, is_recorded: true, is_seen: false, is_available: true, abstract: "Théo Luther est le plus redoutable chef de groupe de la Brigade Criminelle de Paris. Après avoir traqué un tueur d’enfants pendant de longs mois, il fait une dépression et met son mariage en péril...", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "1600 degrés", length_in_mn: 52, year: 2021, is_recorded: true, is_seen: false, is_available: true, abstract: "Théo poursuit la piste d’un homme qui tue des policiers en remontant son histoire personnelle troublée. Mais Alice Morgan n’en a pas fini de le narguer, quitte à jouer un jeu dangereux pour Luther et pour ceux qu’il aime…", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Pile", length_in_mn: 52, year: 2021, is_recorded: true, is_seen: false, is_available: true, abstract: "Des meurtres sans aucune logique apparente sont commis par la même personne dans une station-service et une salle de réalité virtuelle… Sur les images de vidéosurveillance, le tueur semble jouer aux dés. Pendant ce temps, Madsen commence à se réveiller. Il pourrait révéler le secret de Luther…", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Face", length_in_mn: 52, year: 2021, is_recorded: true, is_seen: false, is_available: true, abstract: "Le tueur aux dés continue de frapper de plus en plus fort tandis que Luther commence à déjouer sa logique macabre…", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Shape of Water", french_title: "La Forme de l'eau", length_in_mn: 123, year: 2017, is_recorded: true, is_seen: true, is_available: false, abstract: "Modeste employée d’un laboratoire gouvernemental ultra secret, Elisa mène une existence morne et solitaire, d’autant plus isolée qu’elle est muette. Sa vie bascule à jamais lorsqu’elle et sa collègue Zelda découvrent une expérience encore plus secrète que les autres…", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Parfums, les secrets du ""Made in France"" ", length_in_mn: 52, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Trente-trois millions de flacons de parfums sont vendus chaque année en France. Un symbole de luxe envié dans le monde. Comment crée-t-on un parfum ? Pourquoi coûte-t-il si cher ? Des fleurs aux laboratoires, des ateliers aux distributeurs, focus sur les petits et grands secrets de la parfumerie française.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Retour chez ma mère", length_in_mn: 86, year: 2016, is_recorded: true, is_seen: true, is_available: false, abstract: "À 40 ans, Stéphanie est contrainte de retourner vivre chez sa mère. Elle est accueillie les bras ouverts : à elle les joies de l'appartement surchauffé, de Francis Cabrel en boucle, des parties de Scrabble endiablées et des précieux conseils maternels sur la façon de se tenir à table et de mener sa vie. Chacune va devoir faire preuve d’une infinie patience pour supporter cette nouvelle vie à deux. Et lorsque le reste de la fratrie débarque pour un dîner, règlements de compte et secrets de famille vont se déchaîner. Mais il est des explosions salutaires.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Maroni", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Les fantômes du fleuve", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "Chloé, est une jeune enquêtrice nouvellement affectée à Cayenne en Guyane. Son supérieur hiérarchique l'accueille fraîchement en affirmant qu'il n'est pas dupe ; si elle est affectée en Guyane, c'est forcément une sanction suite à une faute faite en métropole car personne ne demande la Guyane. Il lui présente son nouveau coéquipier Joseph Dialo, originaire de Guyane et connaissant bien la culture et les traditions de ce territoire. Tandis que Joseph fait découvrir à Chloé les spécificités de ce département, un couple de métropolitains est trouvé sauvagement assassiné sur un voilier à la dérive sur le fleuve Maroni. Leur fils de 9 ans a disparu. Chloé et Joseph enquêtent. Le seul témoin est un jeune Bushinengué. Ils suivent une légende provenant d'animisme d'anciens esclaves, et vont devoir remonter le fleuve Maroni.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le territoire des ombres", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "Dans l’hiver de Saint-Pierre-et-Miquelon et Terre-Neuve, le retour en force de l’enquêtrice Chloé Bresson aux prises avec une série de morts violentes. D’une grande richesse narrative, une seconde saison aux confins du fantastique, où les fantômes aident les vivants à supporter leur mélancolie.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Épisode 1", length_in_mn: 47, year: 2020, is_recorded: true, is_seen: false, is_available: true, abstract: "Alors que les recherches pour retrouver son coéquipier Joseph Dialo se poursuivent en Guyane, Chloé doit rentrer à Saint-Pierre-et-Miquelon : sa mère, Gladys, qui commandait la brigade de gendarmerie, vient de se suicider. Chloé doit alors non seulement faire face à une communauté locale pour le moins hostile, mais aussi s’occuper de François, son frère déficient mental, avec qui elle entretient des relations complexes. À la morgue, la jeune enquêtrice remarque une étrange blessure à la tête de Gladys. La découverte dans une décharge du corps d’Alan, un jeune délinquant, va encore compliquer son retour : les soupçons se portent sur François, qui s’est battu avec lui peu avant.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Épisode 2", length_in_mn: 44, year: 2020, is_recorded: true, is_seen: false, is_available: true, abstract: "Tandis que l’enquête officielle dirigée par Yann Legendre, l’ancien bras droit de la mère de Chloé, désigne de plus en plus François comme le suspect numéro un, Chloé se lance dans une enquête parallèle pour innocenter son frère. Elle se retrouve sur la piste d’un mystérieux trafic de drogue auquel Alan aurait participé : celui-ci serait responsable de l’overdose d’une jeune fille de l’île. Trop dérangeante, Chloé se retrouve derrière les barreaux.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Épisode 3", length_in_mn: 44, year: 2020, is_recorded: true, is_seen: false, is_available: true, abstract: "La garde à vue de Chloé prend fin avec l’aide de Marie, la marraine locale. Grâce aux indications de la petite amie d’Alan, Chloé apprend que ce dernier et ses copains – dont Josh, l’un des fils de Marie et frère de David, l’ex de Chloé – se fournissaient en drogue à Terre-Neuve auprès d’un mystérieux Amérindien et qu’ils cachaient la drogue sur leur bateau, le Beothuk. Chloé s’y rend et découvre le corps sans vie de Josh, lardé de coups de couteau. Sur l’île, ce deuxième meurtre suscite des remous, d’autant que Josh et Alan étaient connus pour martyriser régulièrement François… En remontant la piste des Amérindiens, Chloé découvre que l’une d’entre eux est arrivée à Saint-Pierre quelques jours avant le début des meurtres.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Épisode 4", length_in_mn: 48, year: 2020, is_recorded: true, is_seen: false, is_available: true, abstract: "Dans le même temps, Legendre appelle sur place un mystérieux policier amérindien et lui demande de retrouver la jeune Zoé. Chloé découvre que celle-ci s'est donné la mort quelques semaines plus tôt en s'immolant par le feu. Tout laisse à penser qu'elle a été victime de violences sexuelles en même temps que sa meilleure amie, une certaine Shana Jones. C’est chez cette dernière que le policier s’introduit pour la tuer.", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Épisode 5", length_in_mn: 48, year: 2020, is_recorded: true, is_seen: false, is_available: true, abstract: "La gendarme retrouve à la gare routière la trace de la jeune Amérindienne, suivie par un des sbires du tenancier de la boîte de strip-tease où elle travaillait. Au moment où le malfrat veut l’abattre, Chloé s’interpose. Les forces de l’ordre sauvent Shana, mais la confient au policier canadien de mèche avec Alan et Josh. À l’hôpital, Chloé, blessée, apprend une nouvelle qui va changer sa vie...", rank: 5, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Épisode 6", length_in_mn: 46, year: 2020, is_recorded: true, is_seen: false, is_available: true, abstract: "Elle comprend alors ce qu’il a vécu au moment de la mort de leur mère et le rôle qu’il a joué par la suite. Croyant que le troisième violeur est peut-être David – son ex et le frère de Josh –, elle se rend chez lui, mais découvre qu’elle a fait fausse route. Il faut tendre un piège au coupable, dernier survivant du gang maléfique...", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Thunderbolt and Lightfoot", french_title: "Le Canardeur", length_in_mn: 115, year: 1974, is_recorded: true, is_seen: true, is_available: false, abstract: "Le braqueur de banque John « Thunderbolt » Doherty (adapté en le « Canardeur »), se lie d'amitié avec « Pied de Biche » (Lightfoot), un jeune aventurier, qui lui sauve la vie involontairement. Ensemble, ils décident de récupérer un magot d'un demi-million de dollars qu'un complice de Thunderbolt a planqué dans une vieille école. Mais celle-ci a été détruite. Thunderbolt et Lightfoot, rejoints par les anciens complices du premier, mettent au point le braquage d'une autre banque.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le Voyageur", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "Tom Bareski est un commandant de police en disponibilité. Il continue de faire son travail, en marge de la procédure, en enquêtant sur des affaires non élucidées.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 1", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le Voyageur (pilote)", length_in_mn: 90, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Lorsqu'il arrive avec son van dans la ville de Montallier pour enquêter sur une série de disparitions de jeunes filles, Bareski surprend autant les services de police que la population locale.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "La Permission de minuit", length_in_mn: 90, year: 2020, is_recorded: false, is_seen: false, is_available: true, abstract: "Une jeune femme est retrouvée morte dans la région d'Arles, ligotée et allongée nue sur un tas de bois. Thomas Bareski pense que son meurtre est relié à celui de deux autres femmes, survenus en 2012 et en 2017.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le Voleur de nuits", length_in_mn: 90, year: 2020, is_recorded: true, is_seen: false, is_available: true, abstract: "En décembre 1991, à Fougères-sur-Mer, un village de Vendée, Marion, une fillette de sept ans, est enlevée le jour même de son anniversaire. Vingt-neuf ans après, en février 2020, la juge Claire Elgouarch demande à Bareski de reprendre l'enquête, car un élément nouveau est apparu, une lettre de remords de l'assassin, soi-disant vieux et malade. Claire prend cette affaire très à cœur, car c'était son père, un officier de gendarmerie décédé depuis, qui avait mené l'enquête à l'époque.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le village assassiné", length_in_mn: 90, year: 2020, is_recorded: true, is_seen: false, is_available: true, abstract: "0", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Dix jours pour s'aimer", length_in_mn: 90, year: 2011, is_recorded: true, is_seen: true, is_available: false, abstract: "À la suite d'une petite altercation avec la police, un cadre égoïste et carriériste est soumis à dix jours de travaux d'intérêt général et va devoir restaurer la boulangerie d'un petit village du sud-ouest de la France.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Kin", french_title: "Kin : Le Commencement", length_in_mn: 104, year: 2018, is_recorded: true, is_seen: true, is_available: false, abstract: "Jimmy vient de sortir de prison où il a passé six ans. Il retrouve son père Hal et son petit frère adoptif Elijah (dit Eli). Jimmy envisage de trouver un travail honnête, mais son passé le rattrape, sous la forme de Taylor et son frère, deux gangsters auxquels il doit une forte somme. Eli, qui explore des bâtiments abandonnés à la recherche de vieux métaux pour les revendre, tombe dans une usine en ruine sur plusieurs cadavres en armures futuristes, et des armes inconnues.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Armageddon", length_in_mn: 145, year: 1998, is_recorded: true, is_seen: true, is_available: false, abstract: "Alors qu'elle se trouve en mission en orbite terrestre, la navette Atlantis est détruite par une pluie de météorites qui termine sa course sur New York. Ceci est le prélude d'une catastrophe majeure : un astéroïde de la taille du Texas s'écrasera sur Terre dans exactement dix-huit jours. Dan Truman, directeur des opérations de vol à la NASA, envisage la mission de la dernière chance : envoyer des astronautes sur l'astéroïde pour qu'ils y creusent un puits dans lequel sera insérée une charge nucléaire. Pour ce faire, il fait appel à Harry Stamper, le plus grand spécialiste en forage pétrolier. Mais ce dernier, ainsi que ses hommes, n'ont aucune notion d’astronautique, et devront bénéficier d'une formation accélérée.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Amin", length_in_mn: 91, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Amin vit partagé entre la France, où il travaille sur des chantiers, et le Sénégal, où il a laissé sa famille pour gagner de l'argent. Un jour, il rencontre Gabrielle...", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "L'odyssée du loup", length_in_mn: 87, year: 2018, is_recorded: true, is_seen: true, is_available: false, abstract: "Les loups vivent en meute et s'astreignent à une organisation sociale parfaitement structurée autour d'un mâle alpha mais aussi d'individus de milieu de rang et de dernier rang. L'objectif est la protection de chacun des loups composant la meute. Ce documentaire permet de suivre comment un jeune loup banni par ses pairs doit affronter les éléments et survivre dans un monde où les humains est très présent. Des forêts de Roumanie jusqu'aux rivages de l'océan Atlantique, il recherche un nouveau territoire, une nouvelle meute, une nouvelle famille.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Was gewesen wäre", french_title: "Retour à Budapest", length_in_mn: 84, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Lors d’un week-end avec son nouveau compagnon dans la capitale hongroise, une Astrid, une quadragénaire originaire d'Allemagne de l'est, retrouve son premier grand amour. Mais alors que le décor de la capitale hongroise se prête parfaitement à l'idylle, elle croise, dans le grand hôtel où ils sont descendus, Julius, un homme dont elle était follement éprise à l'adolescence. Tentant d'abord d'esquiver leurs retrouvailles inopinées, elle se remémore comment le cours de l'histoire les a séparés, quand, au milieu des années 1980, Julius a choisi de fuir l'Allemagne de l'Est en passant par la Hongrie…", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Jeux d'enfants", length_in_mn: 93, year: 2003, is_recorded: true, is_seen: false, is_available: true, abstract: "Julien, 8 ans, et Sophie deviennent inséparables et s'inventent un jeu : « cap ou pas cap ? ». C'est à celui qui, mis au défi par l'autre, fera les pires bêtises, au grand désespoir des parents. Étudiants, ils continuent à se lancer des défis de plus en plus cruels et même parfois pervers. Après de nombreuses péripéties ponctuées de blessures mutuelles et de longues périodes de froid, ils se mettent au défi de ne plus se voir pendant dix ans. Julien s'est résigné à devenir mature. Il gagne bien sa vie, a une femme et deux enfants. De son côté, Sophie vit en couple avec un joueur professionnel de football riche et célèbre. Le jour d'anniversaire de leur séparation, ils se revoient.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Piano", french_title: "La Leçon de piano", length_in_mn: 121, year: 1993, is_recorded: true, is_seen: false, is_available: true, abstract: "Au XIXe siècle, une jeune femme écossaise, Ada MacGrath est envoyée par son père en Nouvelle-Zélande avec sa fille de neuf ans, Flora, pour y épouser un colon, Alistair Stewart, qu’Ada ne connaît pas. Selon ce que sa fille Flora aime à raconter, Ada n’a pas dit un mot depuis que son premier mari est mort foudroyé alors qu’ils chantaient tous deux dans la forêt ; Ada aurait été chanteuse d'opéra et son mari était son professeur de piano. Mais en réalité, c'est pour une « raison inconnue » qu'elle n’a pas dit un mot depuis l'âge de six ans, et qu’elle a recours à la langue des signes pour s’exprimer, ainsi qu'à son piano. Le piano et la musique de ce film représentent Ada, ses émotions, ce qu'elle exprime.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "La vie secrète du hibou", length_in_mn: 48, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Le Grand-duc d'Amérique est l'un des hiboux les plus réputés et charismatiques, typiques d'Amérique du Nord. Il est très rare de pouvoir les observer.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "L'étonnante histoire de Mme Tussaud et de ses théâtres de cire", length_in_mn: 85, year: 2016, is_recorded: true, is_seen: false, is_available: true, abstract: "Du Paris pré-révolutionnaire au Londres victorien, le destin romanesque de Mme Tussaud (1761-1850), une artisane entrepreneuse qui a fondé un empire toujours florissant.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "La vie secrète des plantes", length_in_mn: nil, year: 2015, is_recorded: false, is_seen: false, is_available: true, abstract: "0", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Propagation", length_in_mn: 44, year: 2015, is_recorded: true, is_seen: true, is_available: true, abstract: "Au fil de l’évolution, les espèces du règne végétal ont mis en place des stratégies ingénieuses et variées afin de se propager sur de nouveaux territoires. Pour faire voyager leurs semences, elles peuvent se servir du vent ou des cours d’eau, mais également des animaux. Certains déplacent ainsi leurs graines par le biais de leur système digestif, de leur pelage ou de leurs plumes.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Appétit", length_in_mn: 44, year: 2015, is_recorded: true, is_seen: true, is_available: true, abstract: "la découverte des incroyables stratégies de survie élaborées par le monde végétal. Pour croître, les plantes ont besoin d’eau, de soleil et de minéraux. Afin de bénéficier de ces ressources indispensables, certaines plantes noient des petites proies ou recueillent des déjections animales, tandis que d’autres se guident grâce à leur ""odorat"" pour atteindre une tige dont elles absorberont l’énergie.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Sexualité", length_in_mn: 43, year: 2015, is_recorded: true, is_seen: true, is_available: true, abstract: "À la découverte des incroyables stratégies de survie du monde végétal. Comment se reproduire lorsqu’on est incapable de se déplacer ? Afin d'assurer la fécondation d’une fleur par le pollen d’une autre, la plupart des plantes doivent faire appel à des alliés de choix : les animaux.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Agatha Christie's Poirot", french_title: "Hercule Poirot", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "Hercule Poirot, ancien policier belge, a fui son pays pendant la Première Guerre mondiale. Désormais, il vit à Londres et exerce en tant que détective privé. Durant les années 1930, sa réputation d'enquêteur hors pair est internationale et de nombreuses personnes font appel à lui pour percer des mystères (souvent des assassinats) que la police n'a pas su résoudre. Dans les premiers temps, Hercule Poirot mène ses enquêtes avec le capitaine Arthur Hastings (un vétéran de la British Army), l'inspecteur James Japp (un policier de Scotland Yard) et Felicity Lemon (la secrétaire de Poirot). Mais, au fil des ans, ses amis s'éloignent de lui (chacun ayant fait sa vie de son côté) et Poirot se retrouve obligé d'enquêter avec la romancière Ariadne Oliver.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 1", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Adventure of the Clapham Cook", french_title: "La Cuisine mystérieuse de Clapham", length_in_mn: 50, year: 1989, is_recorded: false, is_seen: false, is_available: true, abstract: "Hercule Poirot ne semble intéressé par aucune des affaires que lui présente le Capitaine Hastings. C'est alors que Mrs Todd réussit à le convaincre d'enquêter sur la disparition de sa cuisinière, lui faisant remarquer qu'une bonne cuisinière a autant de valeur qu'une pierre précieuse. Mais le lendemain Mr Todd envoie une lettre à Poirot pour décommander ses services et le dédommager avec un chèque d'une guinée, ce qui décuple la volonté du détective de résoudre cette affaire en apparence insignifiante...", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Murder in the Mews", french_title: "Meurtre par procuration", length_in_mn: 50, year: 1989, is_recorded: false, is_seen: false, is_available: true, abstract: "Poirot, Hastings et l'inspecteur Japp se promènent le soir de la Guy Fawkes Night, Hastings leur fait remarquer qu'un coup de feu ne serait pas entendu avec le bruit des feux d'artifice. Le lendemain, l'inspecteur Japp demande à Poirot de l'aider sur une de ses enquêtes: Barbara Allen est retrouvée morte, une balle dans la tête, dans son appartement. Tout semble indiquer un suicide mais certains détails laissent penser à une tout autre histoire. De plus un témoin affirme qu'un homme était présent la veille au soir...", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Adventure of Johnnie Waverly", french_title: "L'Aventure de Johnnie Waverly", length_in_mn: 50, year: 1989, is_recorded: false, is_seen: false, is_available: true, abstract: "Mr et Mrs Waverly reçoivent une lettre leur demandant une grosse somme d'argent s'ils ne veulent pas voir leur fils kidnappé le lendemain à midi. Puisque la police ne prend pas au sérieux les menaces, Mr Waverly fait appel à Poirot. Celui-ci, accompagné de Hastings, se rend dans la demeure de Mr Waverly pour protéger le bambin, et l'inspecteur Japp finit par les rejoindre avec une douzaine d'agents. Mais malgré toutes les précautions prises, le kidnapping a lieu, ce qui laisse penser à l'implication d'un proche...", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Four and Twenty Blackbirds", french_title: "Le mort avait les dents blanches", length_in_mn: 50, year: 1989, is_recorded: false, is_seen: false, is_available: true, abstract: "Dans un restaurant londonien, Poirot converse avec son dentiste des habitudes des gens. La serveuse interrompt leur conversation et leur raconte l'histoire d'un peintre qui vient tous les mercredis et samedis et prend toujours le même plat, sauf que la dernière fois il est venu un lundi et a commandé un plat différent. Poirot est intrigué par le comportement de l'habitué. Quelques jours plus tard, son dentiste lui apprend que le vieil homme a été retrouvé mort chez lui dans l'escalier, la nuque brisée. Son frère était mort quelques jours plus tôt...", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Third Floor Flat", french_title: "L'Appartement du troisième", length_in_mn: 50, year: 1989, is_recorded: false, is_seen: false, is_available: true, abstract: "Cela fait trois semaines que Poirot n'a pas eu de nouvelle enquête et, victime d'un gros rhume, il craint que ses ""petites cellules grises"" dépérissent. Hastings l'emmène au théâtre pour le divertir et, en rentrant, ils entendent du bruit dans l'immeuble. Une voisine a perdu ses clés et ses amis essayent de rentrer dans son appartement par le monte-charge. Mais ils se trompent d'appartement et découvrent le cadavre d'une femme qui venait d'emménager le jour même. Pour la police, le meurtre a été commis par un étranger ce qui n'est pas l'avis de Poirot...", rank: 5, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Triangle at Rhodes", french_title: "Énigme à Rhodes", length_in_mn: 50, year: 1989, is_recorded: false, is_seen: false, is_available: true, abstract: "Poirot part en vacances seul sur l'île de Rhodes. Il y rencontre deux couples de touristes britanniques : les Gold et les Chantry. Dès le début du séjour Mrs Chantry flirte ouvertement avec Mr Gold au grand dam de leurs conjoints respectifs. Poirot n'aimant pas la tournure que prennent les évènements conseille à Mrs Gold de partir si elle tient à la vie. Dans la soirée, Mrs Chantry est empoisonnée mais le verre dans lequel elle a bu était celui de son mari. Mr Gold est arrêté en possession du poison mais Poirot ne croit pas en sa culpabilité...", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Problem at Sea", french_title: "Mystère en mer", length_in_mn: 50, year: 1989, is_recorded: false, is_seen: false, is_available: true, abstract: "Poirot et Hastings sont en croisière en Mer Méditerranée. Le voyage se passe pour le mieux si on met de côté le caractère hautain d'un des voyageurs : Mrs Clapperton. Lors d'une escale à Alexandrie, elle préfère rester à bord pour se reposer. Quelques heures plus tard, elle est retrouvée poignardée dans sa cabine fermée à clef. Entre son mari, le Colonel Clapperton, qui devait supporter les constantes critiques de sa femme, le Général Forbes, amoureux de la victime lors de sa jeunesse, et Miss Henderson, attirée par le colonel, Poirot va devoir jouer de tous ses talents pour trouver le meurtrier...", rank: 7, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Incredible Theft", french_title: "Vol au château", length_in_mn: 50, year: 1989, is_recorded: false, is_seen: false, is_available: true, abstract: "À la veille de la Seconde Guerre mondiale, Mr Mayfield, un industriel britannique, conçoit un nouvel avion technologiquement supérieur à ceux allemands. Il a besoin du soutien financier du gouvernement britannique pour pouvoir continuer ses travaux mais à cause d'une affaire avec les Japonais, il n'est plus dans les bonnes grâces du gouvernement. Il décide de se racheter en tendant un piège à une espionne allemande, Mrs Vanderlyn, et l'invite à passer un week-end chez lui en utilisant les plans de son avion comme appât. Sa femme, Lady Mayfield, demande à Poirot de venir pour garder un œil sur ce qui se passera pendant le week-end, craignant pour la sécurité du pays…", rank: 8, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The King of Clubs", french_title: "Le Roi de trèfle", length_in_mn: 50, year: 1989, is_recorded: true, is_seen: false, is_available: true, abstract: "Poirot et Hastings sont invités sur le tournage du prochain film de Bunny Saunders, un ami réalisateur. Mais le film semble plutôt être dirigé par le directeur du studio, Henry Reedburn, un homme odieux avec tout le monde qui multiplie les avances indécentes envers l'actrice principale, Valérie Saintclair. Reedburn est retrouvé mort le soir même chez lui, dans la bibliothèque, par Saintclair. Le principal bailleur de fonds du film, le Prince Paul de Maurania, demande alors de l'aide à Poirot car il est fiancé à Saintclair et ne peut risquer un scandale si on apprend que celle-ci est impliquée dans une enquête. Poirot rentre en scène mais il est troublé par le fait que Saintclair se soit réfugiée chez les Oglander, qui ne sont pourtant pas les voisins les plus proches de Reedburn...", rank: 9, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Dream", french_title: "Le Songe", length_in_mn: 50, year: 1989, is_recorded: false, is_seen: false, is_available: true, abstract: "Poirot est convoqué par le leader du pâté en croûte, Mr Farley, tard dans la soirée. Celui-ci lui fait part d'un rêve récurrent : il prend son arme dans son bureau, va à la fenêtre et se tire une balle dans la tête. Après avoir vu un psychiatre sans succès, il voudrait maintenant l'avis du détective, mais celui-ci est incapable de lui fournir une réponse qui le satisfait et se fait congédier. Le lendemain, on découvre le corps sans vie de Mr Farley, mort dans les mêmes circonstances que son rêve...", rank: 10, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 10", length_in_mn: nil, year: 2006, is_recorded: false, is_seen: false, is_available: true, abstract: "0", rank: 10, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Mystery of the Blue Train", french_title: "Le Train bleu", length_in_mn: 100, year: 2006, is_recorded: false, is_seen: false, is_available: true, abstract: "Poirot accepte de tenir compagnie à Katherine, une femme qui vient d'hériter d'une grosse fortune, dans le Train Bleu. Mais pendant le voyage la fille d'un magnat du pétrole est battue à mort. Son mari de qui elle voulait divorcer et son amant sont tous deux dans le train. Mais son splendide rubis, le ""Cœur de feu"", est volé ce qui laisse penser à un accident lors d'un vol par un étranger. Poirot va devoir déterminer la raison du meurtre...", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Cards on the Table", french_title: "Cartes sur table", length_in_mn: 100, year: 2006, is_recorded: false, is_seen: false, is_available: true, abstract: "Mr Shaitana, un riche et étrange collectionneur moyen-oriental, invite à dîner quatre personnes qu'il soupçonne chacune d'un meurtre, ainsi que quatre fin limiers : un policier, un colonel des services secrets, la romancière Ariadne Oliver et le détective belge Hercule Poirot. Au cours du repas, l'hôte lance des allusions qui peuvent inquiéter l'un ou l'autre et annonce une révélation pour la fin de la soirée, mais pendant la partie de bridge qui s'ensuit, il est assassiné. Assisté de ses collègues d'un soir et surtout de ses « petites cellules grises », Hercule Poirot enquête...", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "After the Funeral", french_title: "Les Indiscrétions d'Hercule Poirot", length_in_mn: 100, year: 2006, is_recorded: false, is_seen: false, is_available: true, abstract: "Richard Abernethie meurt d'une crise cardiaque, toute la famille se rend à ses funérailles. Lors de l'ouverture de son testament, sa sœur Cora, que personne n'avait revue depuis des années, émet l'hypothèse qu'il aurait été assassiné. Le lendemain, elle est retrouvée massacrée à la hache. Le notaire de la famille fait alors appel à son vieil ami Poirot pour enquêter. Pour le détective belge, l'assassin est un membre de la famille...", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Taken at the Flood", french_title: "Le Flux et le Reflux", length_in_mn: 100, year: 2006, is_recorded: true, is_seen: false, is_available: true, abstract: "Gordon, le membre le plus riche de la famille Cloade épouse la jeune veuve Rosaleen. Quelques jours plus tard il meurt dans une explosion de gaz et toute sa fortune va à sa nouvelle femme. Cependant selon un membre de la famille, l'ex-mari de Rosaleen ne serait pas mort et donc elle ne devrait pas hériter. Alors qu'un étranger s'installe dans le village, Poirot doit retrouver le mari...", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "CSI: NY", french_title: "Les Experts : Manhattan", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "À Manhattan, l'un des cinq arrondissements de New York, une équipe de la police scientifique du NYPD, a recours à la technologie de pointe pour trouver des indices sur les lieux des crimes et résoudre ainsi des enquêtes. Cette équipe est dirigée par Mac Taylor, dont la femme est décédée durant les attentats du 11 septembre 2001.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 9", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 9, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Reignited", french_title: "Rallumer la flamme", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Un immeuble de New York est ravagé par un violent incendie. Le capitaine des pompiers y entre afin de chercher des victimes. Malheureusement, une explosion lui fait perdre la vie. Mac, qui était ami avec le capitaine Curtis Smith, constate rapidement que l'incendie et l'explosion ne sont pas accidentels. L'équipe remarque que le modus operandi est celui de Leonard Brooks, un incendiaire tout juste sorti de prison (après y avoir passé 15 ans). Aurait-il repris ses activités de pyromane ?", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Where There's Smoke…", french_title: "À vif", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Leonard Brooks, un incendiaire, a de nouveau frappé. L'équipe doit absolument l'arrêter pour qu'il ne blesse plus qui que ce soit. Mais ils comprennent très rapidement que, cette fois, ses motivations sont personnelles.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "2,918 Miles", french_title: "La Fille de San Francisco", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Un jeune homme, Ethan Grohl, gît sans vie sur le pont de Brooklyn. Sur lui, les enquêteurs découvrent des photos d'une adolescente étendue sur le sol dans une flaque de sang. Grâce à une lentille de contact, Adam parvient à extraire l'ADN de Boyd Hackman, déjà connu des services de police. Le reste de l'équipe se concentre sur l'analyse des clichés et l'inventaire des communications téléphoniques passées par Ethan.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Unspoken", french_title: "Silence de mort", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Lors d'un rassemblement politique, les experts partent à la recherche d'un tireur parmi la foule. L'arme, dont il s'est débarrassé, finit par être impliquée dans le décès accidentel d'une petite fille.", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Misconceptions", french_title: "Un sombre anniversaire", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Une enquête non résolue datant d'il y a 20 ans vient d'être rouverte. Elle implique la disparition de Tommy Lewis, un petit garçon. Keith Milner, le suspect principal de l'affaire vient d'être assassiné après son retour dans son ancien quartier.", rank: 5, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Lady in the Lake", french_title: "La Dame du lac", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "L'équipe découvre le corps d'une jeune femme habillée en robe de bal près du château du Belvédère. À l'aide de ses empreintes, Sid découvre qu'il s'agit d'une jeune collégienne, Ashley Braden. Jo découvre également sur sa robe une tache de sang appartenant à Joseph Skiver. Un interrogatoire du jeune homme révèle qu'il était sorti avec la jeune fille quelque temps auparavant.", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Clue: SI", french_title: "Jeu de meurtres", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Les experts enquêtent sur une série de meurtres, dont les victimes, lieux et armes rappellent les éléments d'un célèbre jeu de société : le Cluedo", rank: 7, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Late Admissions", french_title: "Réussite sur ordonnance", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Les experts enquêtent sur le meurtre de Luke Stevenson, un lycéen et trouvent un lien avec un de ses camarades de classe, qui vend des médicaments soumis à prescription médicale.", rank: 8, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Blood Out", french_title: "L'Infiltrée", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Les experts enquêtent sur le meurtre de Benny Madera, un membre d'un gang dominicain, retrouvé coupé en deux avec une tronçonneuse, et qui avait un lien avec la nouvelle partenaire de Flack, Jamie Lovato, qui avait infiltré le gang pour son ancien service.", rank: 9, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Real McCoy", french_title: "Bar clandestin", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Les experts enquêtent sur le meurtre de Jason Black, copropriétaire d'un bar clandestin et populaire appelé « The Real McCoy ». L'homme a été dépouillé d'une grosse somme d'argent. En étudiant le corps, Hawkes découvre des traces de sang sur la montre du défunt. L'analyse ADN de l'échantillon permet à l'équipe de remonter jusqu'à un certain Nathan Brody. Les experts découvrent également que de l'alcool contrefait contenant du méthanol circulait au sein du bar. De son côté, Adam essaie de régler des problèmes non résolus tout en s'occupant de son père malade. Suivant les conseils de Christine, Mac décide de profiter de son jour de liberté.", rank: 10, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Command+P", french_title: "L'Ange gardien", length_in_mn: 42, year: 2013, is_recorded: true, is_seen: false, is_available: true, abstract: "Deux individus sont retrouvés morts, assassinés selon le même modus operandi. Dans le même temps, des chèques anonymes d'un montant d'un million de dollars sont disséminés aux quatre coins de la ville par un mystérieux bienfaiteur.", rank: 11, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Civilized Lies", french_title: "Mise en scène", length_in_mn: 42, year: 2013, is_recorded: true, is_seen: false, is_available: true, abstract: "Un officier de police est tué pendant un braquage. Les experts s'interrogent au sujet d'un blessé par balle détenu par la police. Ils se demandent s'il s'agit d'un simple témoin oculaire ou s'il faisait partie des voleurs.", rank: 12, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Nine Thirteen", french_title: "L'Immeuble maudit", length_in_mn: 42, year: 2013, is_recorded: true, is_seen: false, is_available: true, abstract: "Les experts enquêtent sur le meurtre d'un homme masqué qui a fait une chute vertigineuse d'un gratte-ciel, réputé pour être maudit. Cette victime serait la 37e à être décédée de manière inexpliquée à cette adresse. Les policiers découvrent qu'il travaillait dans une boîte de nuit située dans l'immeuble et en profitait pour voler des touristes. Parallèlement, Jo rencontre un homme ayant un lien inattendu avec son passé.", rank: 13, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "White Gold", french_title: "L'Or blanc", length_in_mn: 42, year: 2013, is_recorded: true, is_seen: false, is_available: true, abstract: "Des tagueurs qui vandalisent leur quartier sont témoins d'un accident suivi d'un meurtre. Danny identifie la victime comme étant Paul Tortucci, un cuisinier travaillant dans une pizzeria réputée. Mac se rend dans le restaurant pour informer son oncle de son décès. Il lui révèle aussi que selon toute vraisemblance, le défunt faisait de la contrebande. De son côté, Danny rencontre la propriétaire d'une des voitures impliquées dans le drame.", rank: 14, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Seth and Apep", french_title: "Un retour pour New York", length_in_mn: 42, year: 2013, is_recorded: true, is_seen: false, is_available: true, abstract: "D.B. Russell est en route pour New York pour aider Mac à localiser les ravisseurs de Christine avant qu'il ne soit trop tard. Ils décident de se servir de Jimmy Boyd pour approcher les malfaiteurs, mais le rendez-vous mis au point tourne mal. Mac parvient néanmoins à neutraliser l'un d'eux qui refuse de révéler l'endroit où Christine et le frère de Jimmy sont retenus captifs et le nom de son commanditaire.", rank: 15, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Blood Actually", french_title: "Fatale St-Valentin", length_in_mn: 42, year: 2013, is_recorded: true, is_seen: false, is_available: true, abstract: "Épisode formé de 3 petits épisodes : Amour à vendre, L'Amour est aveugle, Au nom de l'Amour. Dans 'Amour à vendre', un homme est mort dans une chambre d’hôtel avec fraises au chocolat, champagne et bonbons en forme de cœur. Dans 'L'Amour est aveugle' un homme, est tombé sur sa table basse en verre, décédé au milieu de chocolat en tous genres. Dans 'Au nom de l'Amour', un homme rejoint sa femme et se fait tirer dessus en pleine rue alors qu'il a un bouquet de roses à la main. Qui sont les tueurs ? Y a-t-il légitime défense, des meurtres passionnels ou commis au hasard ? Seules les enquêtes de Lindsay, Jo, Danny, Sheldon et de Mac peuvent le dire ! Dans le même temps, les experts songent aussi à la soirée qu'ils vont passer en cette date particulière. Si Jo se désole de n'avoir aucun projet, Christine se réjouit à l'idée d'aller au restaurant avec Mac.", rank: 16, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Today is Life", french_title: "Un dernier au revoir", length_in_mn: 42, year: 2013, is_recorded: true, is_seen: false, is_available: true, abstract: "À l'issue d'une course-poursuite, un policier abat un homme de couleur qui venait de cambrioler une bijouterie. Aussitôt, la communauté noire organise une manifestation pour protester contre ce qu'elle considère être un crime raciste. Don et Mac interrogent le jeune officier pour connaître les détails de l'intervention. Les première pièces à conviction collectées sont en contradiction avec sa version des faits, mais de nouveaux éléments laissent penser qu'il pourrait y avoir une autre explication.", rank: 17, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 8", length_in_mn: nil, year: 2011, is_recorded: false, is_seen: false, is_available: true, abstract: "0", rank: 8, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Indelible", french_title: "Travail de mémoire", length_in_mn: 42, year: 2011, is_recorded: true, is_seen: false, is_available: true, abstract: "La cérémonie des 10 ans du 11 septembre est un moment déchirant pour Mac qui se remémore le déroulement de sa matinée ce jour-là, et la disparition non-élucidée de son épouse Claire lors des attentats, supposée décédée depuis, faute de comparaison d'ADN possible. Mac a quitté momentanément l'équipe pour faire des recherches scientifiques, afin d'aider des familles à en savoir plus sur des disparus lors des attentats. Les membres de l'équipe se souviennent eux aussi à diverses occasions d'où ils étaient alors, et ce qu'ils ont fait… Pendant ce temps, l'enquête sur un vol suivi d'un homicide à la sortie d'un bar va s'avérer plus compliquée que ce qu'il semblait de prime abord.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Keep It Real", french_title: "La Couleur de l'argent", length_in_mn: 42, year: 2011, is_recorded: true, is_seen: false, is_available: true, abstract: "Les experts enquêtent sur une seule enquête. Michael Schaefer a été retrouvé mort dans son appartement, après avoir passé la nuit en compagnie d'une certaine Miranda. Celle-ci prétend avoir entendu des coups de feu alors qu'elle dormait et qu'arrivant dans le salon, elle avait découvert le corps de Michael. Il semblerait que la victime ait tenté de se défendre, avant d'avoir été abattue à bout portant. Les enquêteurs se lancent à la recherche de Josh, colocataire de Michael, qui a mystérieusement disparu. L'enquête met en lumière une affaire de faux billets…", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Cavallino Rampante", french_title: "Business familial", length_in_mn: 42, year: 2011, is_recorded: true, is_seen: false, is_available: true, abstract: "Les experts enquêtent sur une seule affaire. Danny et sa nouvelle coéquipière découvrent durant leur patrouille le corps d'une jeune femme dans le coffre d'une Ferrari volée. Appelés à la rescousse, ses collègues recherchent des indices sur place ainsi que dans la voiture. La victime a-t-elle été tuée là ou ailleurs ? Bientôt, l'identité de la jeune femme est déterminée : Michelle Moore est une voleuse de voitures, membre d'une famille spécialisée dans le braquage d'automobiles. Elle avait d'ailleurs volé la Ferrari dans laquelle on l'a retrouvée. Les experts ont alors une certitude : ils doivent identifier et arrêter l'assassin au plus vite s'ils ne veulent pas que toute la famille de la défunte ne subisse le même sort qu'elle. Un indice essentiel est un résidu de poudre médicale découvert dans l'automobile...", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Officer Involved", french_title: "Suspect Messer", length_in_mn: 42, year: 2011, is_recorded: true, is_seen: false, is_available: true, abstract: "Danny et ses collègues sont sortis se détendre autour d'un verre. Mais leur soirée tourne au cauchemar : tous sont, pris dans une fusillade qui éclate devant le bar. Danny est surpris par un homme qui lui casse une bouteille sur la tête L'agent Lauren Cooper, récemment enrôlée dans l'équipe, prend alors l'arme de Danny et tire sur l'homme. Elle prétend qu'elle a agi en état de légitime défense mais, malheureusement, on ne retrouve pas d'arme près du cadavre de l'homme qu'elle a abattu. Danny vit très mal la situation et s'interroge sur ses capacités à gérer ses troupes. Pourquoi a-t-il bu ce soir-là ? Comment gère-t-il sa relation avec Lauren ? Tout s'emballe lorsqu'il est démontré que Lauren a menti sur les circonstances de la fusillade.", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Air Apparent", french_title: "Fratries", length_in_mn: 42, year: 2011, is_recorded: true, is_seen: false, is_available: true, abstract: "Riley Frazier, jeune prodige du basket américain, joue un match important. Hank, son frère, junkie notoire, est en prison. Dans sa cellule, il écoute le match à la radio. Quand arrive le jour tant attendu de sa libération, Hank promet de ne plus toucher à la drogue. Il se réjouit de revoir les siens, et en particulier sa petite amie Angela. Mais celle-ci est retrouvée morte, assassinée de dix coups de poignard. À côté du cadavre, le prénom de Hank est écrit avec le sang de la victime. Le coupable semble tout trouvé, mais les enquêteurs demeurent sceptiques. L'autopsie révèle en effet que le premier coup avait rendu la jeune femme incapable d'écrire...", rank: 5, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Get me Out of Here!", french_title: "De tombe en tombe", length_in_mn: 42, year: 2011, is_recorded: true, is_seen: false, is_available: true, abstract: "Le jour d'Halloween, le corps d'un étudiant nommé Paul Warren est retrouvé dans un cimetière, dans une tombe ouverte. L'équipe découvre que Warren était « maître des bizus » dans une fraternité et qu'un autre garçon est peut-être en danger...", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Crushed", french_title: "Cruelles chutes", length_in_mn: 42, year: 2011, is_recorded: true, is_seen: false, is_available: true, abstract: "Libby Drake, une adolescente est retrouvée morte lors d'une fête. Ce qui paraissait être un accident se révèle rapidement être un meurtre. On découvre qu'elle humiliait certains de ses camarades sur les réseaux sociaux.", rank: 7, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Crossroads", french_title: "De vieilles connaissances", length_in_mn: 42, year: 2011, is_recorded: true, is_seen: false, is_available: true, abstract: "Les Experts enquêtent sur le meurtre d'un magistrat survenu alors qu'il présidait un important procès. Ils découvrent qu'au début de sa carrière, il a été corrompu et a fait emprisonner des enfants.", rank: 8, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Means to an End", french_title: "... les grands remèdes", length_in_mn: 42, year: 2011, is_recorded: true, is_seen: false, is_available: true, abstract: "Les Experts enquêtent sur le viol d'une femme dont le témoignage est incohérent avec les preuves recueillies. Jo découvre qu'un de ses vieux amis du FBI est certainement impliqué dans cette affaire de falsification.", rank: 9, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Clean Sweep", french_title: "Quitter la cage", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Un corps calciné vient d'être découvert. Les experts sont aussitôt envoyés sur place pour recueillir des indices et tenter d'identifier le cadavre. Les analyses révèlent que le défunt était Ryan Richards, un sportif qui participait à des combats. Les interrogatoires commencent aussitôt dans l'entourage de la victime. Celle-ci n'avait pas que des amis dans le milieu de la compétition et des témoignages concordants démontrent que quelqu'un le harcelait. Pourtant, plusieurs pièces du puzzle ne collent pas avec la théorie du meurtre. Mac en arrive même à se demander si le sportif n'a pas organisé sa mort pour faire accuser une personne en particulier...", rank: 10, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Who's There?", french_title: "La guerre des nerfs", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Lorsque deux hommes armés pénètrent chez Elizabeth et Ron Ferguson, l'attaque se solde par la mort de Ron. Elizabeth est blessée. Le riche couple ne se connaissait pas d'ennemis et la police songe à un vol qui aurait mal tourné. Les experts commencent leur travail sur la scène de crime et découvrent un fragment de carte à jouer sur le corps de la victime.", rank: 11, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Brooklyn 'Til I Die", french_title: "Jeu de pistes à Manhattan", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Un homme gagne une forte somme dans un casino. Lorsqu'il sort avec sa copine, ils sont braqués par deux malfrats, qui abattent la jeune femme ; l’homme disparaît. Les experts enquêtent sur cette affaire de meurtre et d'enlèvement. Ils découvrent qu'en réalité le couple avait joué à un jeu de rôle et que l'argent gagné n'était pas du vrai argent. Peu de temps après, le père de la victime enlevée reçoit une demande de rançon : quatre millions de dollars doivent être versés bientôt ; un petit doigt tranché de la victime est joint à la demande de rançon.", rank: 12, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Ripple Effect", french_title: "L'effet ricochet", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Mac et son équipe enquêtent sur le cas d'un coursier a vélo qui est retrouvé mort en bas des escaliers d'une ruelle. Il s'agirait d'une mauvaise chute mais la victime fuyait quelqu'un. En parallèle, un joggeur est retrouvé transpercé d'une flèche et accroché à un arbre. La victime aurait d'abord été étranglée. Les deux affaires seraient liées.", rank: 13, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Flash Pop", french_title: "Rouge tempête", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Mac reçoit la photo d’une scène de crime sur son téléphone portable qui lui semble familière. Après vérification, il s'agit d'une copie quasi-exacte d’un meurtre non résolu de 1957. Ce n’est qu’une fois sur place qu’il réalise que la victime travaillait dans son laboratoire, comme technicienne. Très vite, l’enquête révèle que le meurtrier travaille lui aussi au laboratoire.", rank: 14, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Kill Screen", french_title: "Derrière l'écran", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Un cadavre enveloppé dans une bâche en plastique est retrouvé. Les Experts découvrent que la victime, portant des vêtements d'arbitre, était impliquée dans l'organisation d'un important tournoi de jeux vidéo.", rank: 15, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Sláinte", french_title: "Aux quatre coins de l'enfer", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "L'équipe des experts new-yorkais essaie d'identifier l'auteur du meurtre de Michael Byrne, un commerçant, dont le corps a été atrocement réparti aux quatre coins de Manhattan.", rank: 16, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Unwrapped", french_title: "Cadeau empoisonné", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Kelvin Moore, un homme connu et respecté de son quartier est tué sous les yeux de sa femme, Elaine. Mais après l'autopsie de Sid, les experts apprennent que la version du témoin est fausse, elle est retrouvée plus tard chez leur suspect principal, celui-ci leur fournit un indice, un chat en porcelaine qui transportait de la drogue. Elaine et sa sœur doivent livrer cette drogue de force sinon la nièce d'Elaine risque d'être tuée. Néanmoins il reste à savoir comment le meurtrier encore dans la nature savait qu'Elaine et son mari étaient en possession de cette drogue, ce qui a coûté la vie à Kelvin.", rank: 17, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Near Death", french_title: "Mort imminente", length_in_mn: 42, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Mac est entre la vie et la mort après avoir été blessé par balle lors du braquage d'une pharmacie. L'équipe va tout mettre en œuvre pour retrouver le tireur.", rank: 18, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Groenland, les derniers chasseurs des glaces", length_in_mn: 71, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Les chasseurs inuit ont longtemps vécu en autarcie sur la côte du Groenland oriental. Avec l'interdiction en 2009 du commerce de la fourrure de phoque, leur communauté a vu son maigre revenu économique se tarir. On assiste ainsi à la lente disparition de cette culture autochtone, sous l'influence du monde extérieur et de la dépendance aux aides étrangères.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Épisode 1", length_in_mn: 45, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Premiers pas en Guyane, première affaire d’envergure. Dès son arrivée à Cayenne, Chloé Bresson, enquêtrice de la gendarmerie, a le sentiment de perdre pied. Déterminée à faire ses preuves, la jeune femme cache ses hésitations à son partenaire. Guyanais d’origine, Joseph Dialo connaît bien ce territoire et les mystères qu’il recèle. Le meurtre d’un couple de métropolitains sur leur voilier et la disparition de leur fils de 8 ans conduisent les deux coéquipiers à surmonter leur défiance réciproque et à suivre la piste d’un crime rituel.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Épisode 2", length_in_mn: 45, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "S’immergeant dans les mystères du vaudou, Chloé et Dialo remontent jusqu’à un premier suspect et libèrent une jeune femme brésilienne entrée illégalement sur le territoire. Chacun de leur côté, ils progressent sur l’affaire : Chloé en explorant la piste d’un trafic d’animaux, Dialo en s’enfonçant dans les réseaux de prostitution qui gangrènent Cayenne.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Épisode 3", length_in_mn: 45, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "L’enquête de Chloé l’amène à retrouver l'auteur de l'enlèvement du petit Jean Hugain. Coupable d'une faute professionnelle, Dialo est contraint de quitter la police. Mais il n'arrête pas pour autant ses recherches. Délaissant Cayenne pour Saint-Laurent-du-Maroni, il poursuit ses investigations sur les traces de son propre passé. Désorientée, Chloé part à sa recherche.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Épisode 4", length_in_mn: 45, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "S’enfonçant toujours plus loin dans la forêt, Chloé et Dialo découvrent l’existence d’un culte vaudou, l’Iskander. Dialo comprend peu à peu que pour résoudre cette enquête, il va devoir lever le voile sur le mystère qui entoure son enfance…", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "La saga des feuilletons et des séries", length_in_mn: 146, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Depuis 70 ans, la télévision française a vu passer de nombreuses séries et feuilletons, aux personnages mémorables. Plusieurs générations de téléspectateurs ont grandi en suivant leurs aventures, qu'ils soient héros de l'histoire de France, policiers ou femmes de caractère. Sagas de l'été, sitcoms, feuilletons quotidiens et séries en costume ont jalonné l'histoire populaire et restent ancrés dans les souvenirs des Français. Les acteurs et témoins de ces programmes inoubliables racontent l'histoire de ces années de télévision et livrent lors d'interviews inédites anecdotes et secrets de tournage.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Scorpion", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "Walter O'Brien et son équipe de surdoués sont recrutés par l'agent fédéral Cabe Gallo du Département de la Sécurité intérieure des États-Unis pour former Scorpion, une unité censée être la dernière ligne de défense contre les menaces complexes, de haute technologie dans le monde entier. L'équipe comprend Walter O'Brien, l'une des personnes les plus intelligentes au monde avec un QI de 197, et ses amis Sylvester Dodd, une « calculatrice humaine » et génie en statistiques, Happy Quinn, une « prodige de la mécanique » et Toby Curtis, un « psychiatre de classe mondiale » (un comportementaliste formé à Harvard). Le groupe est complété par Paige Dineen, une ancienne serveuse qui doit gérer les interactions entre ces génies de l'équipe et les gens « normaux » en leur traduisant le monde réel ; eux, en échange, lui traduisent le monde tel qu'il est perçu par son jeune fils, Ralph, lui-même doté de capacités intellectuelles hors-normes.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 1", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 2", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 3", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 4", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Extinction", french_title: "Y a-t-il un génie pour sauver le monde ? - partie 1", length_in_mn: 42, year: nil, is_recorded: true, is_seen: false, is_available: true, abstract: "Les nouvelles troublantes dévoilées par Mark Collins à l'équipe Scorpion poussent Walter et ses acolytes à collaborer malgré eux avec leur pire ennemi.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "More Extinction", french_title: "Y a-t-il un génie pour sauver le monde ? - partie 2", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "L'équipe est contrainte de s'affranchir des règles dans l'espoir d'empêcher la survenue d'une catastrophe mondiale. Cabe fait face aux conséquences de ses choix.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Grow a Deer, A Female Deer", french_title: "Hakuna Matata", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Confrontés à des problèmes financiers, les membres de l'équipe Scorpion se rendent en Afrique pour empêcher une bande de braconniers de sévir.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Nuke Kids on the Block", french_title: "L'union faire la force", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "L'équipe intervient sur un ancien site militaire renfermant un missile nucléaire, tandis que les erreurs d'Happy finissent par insupporter Paige.", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Sci Hard", french_title: "Otages", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Walter et Paige se rendent à une convention sur les nouvelles technologies où se pressent des invités inattendus. Sly tente de décrocher son examen.", rank: 5, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Queen Scary", french_title: "Le vaisseau fantôme", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "L'équipe inspecte le Queen Mary après avoir été engagée par un documentariste souhaitant prouver ou réfuter une fois pour toutes l'existence des fantômes.", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Go with the Flo(rence)", french_title: "Rats de villes et rats d'égouts", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Une nouvelle voisine fait son apparition, l'équipe inspecte les égouts à la recherche d'un puissant gadget, et Cabe et Toby discutent du procès à venir.", rank: 7, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Faire is Foul", french_title: "Voyage dans le temps", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "La carrière de Sly connaît des débuts houleux. L'équipe se rend à un festival de la Renaissance. Walter tente de recoller les morceaux avec Paige.", rank: 8, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "It's Raining Men (of War)", french_title: "Le radeau des méduses", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Walter, Happy et Flo prennent le large pour tenter de détruire une île flottante constituée de déchets plastiques.", rank: 9, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Crime Every Mountain", french_title: "Crime en famille", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Alors que la tension monte entre Walter et Cabe, l'équipe n'a pas une minute à perdre pour venir en aide aux victimes d'un crash d'avion.", rank: 10, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Who Let the Dog Out ('Cause Now It's Stuck In a Cistern)", french_title: "Une journée de chien", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Stressée par le procès de Cabe, l'équipe tente de se concentrer sur des choses positives en volant au secours d'un chien diabétique coincé sous terre.", rank: 11, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "A Christmas Car-Roll", french_title: "En plein délire !", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Après s'être cogné la tête en tombant pendant la nuit de Noël, Walter imagine une vie dans laquelle l'équipe Scorpion n'aurait jamais existé.", rank: 12, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Bunker Games", french_title: "Les révoltés du bunker", length_in_mn: 42, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "En testant un bunker apocalyptique doté d'une intelligence artificielle, l'équipe découvre un certain nombre de dysfonctionnements.", rank: 13, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Lighthouse of the Rising Sun", french_title: "Un phare dans la nuit", length_in_mn: 42, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Deux ados aux commandes d'un petit avion voient leur vie menacée quand une panne de courant massive coupe toute communication avec le sol.", rank: 14, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Wave Goodbye", french_title: "Alerte tsunami", length_in_mn: 42, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Un tsunami menace de détruire une vieille centrale nucléaire située au Mexique. À Los Angeles, Toby aide une ex-fiancée à retrouver son identité.", rank: 15, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Nerd, Wind and Fire", french_title: "Opération Saint-Valentin", length_in_mn: 42, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Il y a de l'amour dans l'air pour la Saint-Valentin, du moins c'est ce qu'espère Ralph ! Un crash d'hélicoptère requiert l'intervention immédiate de l'équipe Scorpion.", rank: 16, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Dumbster Fire", french_title: "Rendez-moi mon QI", length_in_mn: 42, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Alors qu'ils visitent un laboratoire souterrain caché dans les Rocheuses, les membres de l'équipe Scorpion voient leurs facultés intellectuelles étrangement diminuées.", rank: 17, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Dork Day Afternoon", french_title: "La bourse ou la vie", length_in_mn: 42, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Pour arriver à la clinique à temps alors qu'un hold-up est en cours à la banque, l'équipe Scorpion va devoir faire preuve d'ingéniosité.", rank: 18, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Gator Done", french_title: "Les dents du bayou", length_in_mn: 42, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Les membres de l'équipe se rendent à La Nouvelle-Orléans pour combattre une épidémie de moustiques. Sly et Ralph emploient les grands moyens pour venir en aide à Patty.", rank: 19, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Foul Balls", french_title: "Le sport pour les nuls", length_in_mn: 42, year: 2018, is_recorded: false, is_seen: false, is_available: true, abstract: "Contrainte de participer à un tournoi de softball organisé par le gouvernement, l'équipe Scorpion ramène sa science pour tenter de briller sur le terrain.", rank: 20, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Kenny and the Jet", french_title: "Le passager clandestin", length_in_mn: 42, year: 2018, is_recorded: false, is_seen: false, is_available: true, abstract: "Les membres de l'équipe font une découverte troublante dans la roue de leur avion. Walter ne peut cacher sa culpabilité. Cabe tente d'encourager Sly.", rank: 21, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "A Lie in the Sand", french_title: "Une tempête peut en cacher une autre", length_in_mn: 42, year: 2018, is_recorded: false, is_seen: false, is_available: true, abstract: "L'équipe Scorpion se rend en mission en Afrique. Happy et Toby prennent une grande décision. La relation de Paige et Walter prend un nouveau tournant.", rank: 22, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Sieben Stunden", french_title: "Sept heures avec un tueur", length_in_mn: 88, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Une psychologue réputée est prise en otage par un détenu de la prison de haute sécurité pour laquelle elle travaille. Le courageux combat d'une femme pour sa reconstruction.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Mortelles calanques", length_in_mn: 92, year: 2020, is_recorded: false, is_seen: false, is_available: true, abstract: "Robin, 25 ans, est l'un des meilleurs plongeurs des calanques. Avec son ami Matthieu, il se rend à la calanque d'En Vau, à Cassis, réputée pour ses ""à pic"" de plus de 20 mètres. Il est 17 h, Robin plonge avant Mathieu, mais ne remonte pas. Ou plutôt il remonte au bout de deux longues minutes, comme rejeté par la mer, noyé. La mort d'un plongeur aussi expérimenté paraît suspecte. La Maréchale des Logis chef Emilie Pradot est chargée de l'enquête. Elle commence par interroger Matthieu. Pour lui, c'est incompréhensible, cet endroit, ils le connaissent comme leur poche. Bruno Tourneur, ancien nageur de combat militaire, est l'expert envoyé par la gendarmerie pour épauler Elodie...", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 4", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres à La Ciotat", length_in_mn: 90, year: 2016, is_recorded: true, is_seen: false, is_available: true, abstract: "Un corps est découvert pendu dans un hangar des chantiers navals de La Ciotat. Anne Sauvaire, une jeune commissaire, est chargée de l'affaire. Ses collègues ne lui font guère confiance et le procureur lui met une certaine pression. De plus, elle se voit contrainte de collaborer avec un journaliste, Batti Vergniot, qui connaît bien la ville et son histoire. Cela tombe bien car la clé de l'affaire semble se situer dans les secrets d'un événement qui s'est déroulé le 2 novembre 1980, en plein conflits sociaux et l'omertà règne à La Ciotat. Un deuxième meurtre complique encore l'affaire1,2...", rank: 19, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres à Saint-Malo", length_in_mn: 90, year: 2013, is_recorded: true, is_seen: true, is_available: true, abstract: "Gwenaële Garrec, lieutenant de la PJ de Rennes, est envoyée pour enquêter sur la découverte d'un cadavre sur la plage de Saint-Malo. Durant l'enquête, elle collabore avec Éric Vautier, un adjudant-chef de la gendarmerie. Selon Gwenaëlle, leur affaire est liée à la piraterie, puisque la victime porte les marques de tortures des corsaires remontant au XVIIe siècle.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres au Pays basque", length_in_mn: 96, year: 2014, is_recorded: true, is_seen: true, is_available: true, abstract: "Une femme est retrouvée morte affreusement torturée près de Saint-Jean-de-Luz. Le capitaine Marie Daguerre mène l'enquête accompagnée et encombrée par le revêche commandant Becker, flic parisien, qui se trouve être le père du principal suspect disparu.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Meurtre au Pyla", french_title: "La Disparue du Pyla (HS01)", length_in_mn: 98, year: 2014, is_recorded: true, is_seen: true, is_available: true, abstract: "Élise Castelle, journaliste à Bordeaux, apprend qu'un corps a été découvert enterré au Pyla-sur-Mer, lors d'un chantier de construction dans les prés salés. Persuadée qu'il s'agit de sa sœur, Laura, disparue en septembre 1998, elle revient dans son village d'enfance.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres à Rocamadour", length_in_mn: 99, year: 2014, is_recorded: true, is_seen: true, is_available: true, abstract: "Le capitaine Sophie Lacaze et son futur successeur, le capitaine Alexandre Delcroix, mènent une enquête sur la mort d'un homme retrouvé sur les marches du Chemin du Pénitent à Rocamadour, et sur l'enlèvement de sa petite fille de huit ans.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Meurtres à l'abbaye de Rouen", french_title: "Meurtres Rouen", length_in_mn: 90, year: 2014, is_recorded: true, is_seen: true, is_available: true, abstract: "Didier Mège, capitaine de police, revient à Rouen, sa ville natale, pour se rapprocher de son père dont la santé décline. À peine installé, il est appelé sur une scène de crime : un cadavre a été retrouvé au pied de l’Abbatiale Saint-Ouen. Un homme est tombé des toits. Accident ? Suicide ? Meurtre ? L’étrange position du corps intrigue Didier. Il se souvient l’avoir vu tous les jours, étant petit, sur l’un des vitraux fabriqué par son grand-père, sur le chef-d'œuvre que le maître verrier avait réalisé pour la fin de ses études. Didier découvre alors que ce meurtre est lié à un sombre secret qui hante sa propre famille depuis deux générations…", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Les Mystères de l'île (HS04)", length_in_mn: 90, year: 2017, is_recorded: false, is_seen: false, is_available: true, abstract: "Un corps sans vie est retrouvé sur un zodiac à la dérive au large de Fort Boyard. Sur l'île d'Aix, l'inspectrice Solène mène l'enquête. Elle demande au maire de la ville, Vincent, de la seconder dans son enquête. Personne ne reconnaît le défunt mais une fois à Fort Boyard, Solène et son adjoint, Adrien, découvrent qu'il en était le nouveau gardien, nommé José Chebec.", rank: 20, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres à Dunkerque", length_in_mn: 90, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Un homme est retrouvé mort, pendu en haut d'un mât d'un vieux gréement pendant le carnaval de Dunkerque. L'enquête est confiée au capitaine Janie Roussel et au lieutenant Éric Dampierre, fraîchement débarqué dans le Nord. Janie Roussel connait bien milieu du Carnaval, et notamment les différentes associations dont les Corsaires, dont faisait partie la victime, Marc Vandernoot. Elle s'entend facilement avec son jeune collègue dont l'esprit analytique compense sa méconnaissance de la ville et de ses traditions.", rank: 21, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres en Martinique", length_in_mn: 96, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Au moment où Léna Valrose, policière d'ascendance martiniquaise, arrive de métropole, un corps est retrouvé à la montagne Pelée. Vu les circonstances, le stage qu'elle devait animer est annulé et elle doit porter assistance à Paul Ventura pour l'enquête. L'arrivée de Léna en Martinique n'a cependant pas qu'un but professionnel. Elle est également à la recherche de son père.", rank: 22, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres à Porquerolles/Le Sang des îles d'or (HS05)", length_in_mn: 90, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Alors qu'elle a démissionné de la police après avoir échoué à traquer le tueur qui a assassiné sa nièce, la Commandant Sandra Pantakidis a décidé de se retirer sur l'Ile de Porquerolles, où elle s'adonne maintenant à la plongée sous-marine et initie les enfants des écoles. C'est alors qu'un deuxième crime survient, en tout point similaire au premier. Par défi, le tueur envoie à la police une balle de l'arme qu'il a volée à Sandra 3 ans plus tôt et avec laquelle il a abattu son adjoint. Malgré cet ""appel"" du tueur, Sandra renonce à apporter son aide à l'enquête... Jusqu'à ce qu'elle découvre qu'Ariane, sa fille - ex avocate avec laquelle elle est en froid - s'est engagée dans la police et a pris son fauteuil à la tête du Groupe Crime que Sandra a dirigé...Poussée par le désir ""d'exorciser son passé"", Sandra fera tout pour protéger sa fille.", rank: 23, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres à La Bourboule/Sources assassines (HS06)", length_in_mn: 91, year: 2017, is_recorded: false, is_seen: false, is_available: true, abstract: "Dans la ville thermale de La Bourboule, un homme est retrouvé mort empoisonné... Son ex-compagne, Irène, médecin chef des thermes, possède un important stock d’arsenic médical qui pourrait être l’arme du crime. Elle est accusée du meurtre et placée en garde à vue. Appelée à la rescousse, sa fille Fanny, jeune capitaine à la Crim' de Paris qu'elle n'a pas vue depuis des années, va tenter d'innocenter sa mère et de découvrir la vérité. Entre testament, liaisons amoureuses, intérêts commerciaux et vengeance, l'enquête de Fanny va la mener bien plus loin qu'elle ne l'imaginait en la plongeant dans ses propres secrets de famille.", rank: 24, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres à Bastia/Tensions au Cap Corse (H07)", length_in_mn: 100, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Un homme d'affaires à la réputation sulfureuse est retrouvé assassiné sur la jetée du port de Toga. Détail énigmatique et frappant : ses oreilles ont été tranchées. Pour le commandant Gabrielle Monti dont c'est la dernière affaire depuis son retour au pays, démarre une investigation sur la corde raide, entre passé et présent. Gabrielle doit faire ses preuves dans une enquête où la victime a été autrefois suspectée de chantage et de meurtre par son père, le juge d'instruction Xavier Monti. Un père avec lequel Gabrielle a toujours entretenu des relations conflictuelles depuis la mort de son frère, survenue trente ans plus tôt.", rank: 25, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres à Grasse", length_in_mn: 90, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Lors d'une visite guidée au musée de la parfumerie, à Grasse, Sophie Mournel découvre le corps d'un homme dans une cuve à enfleurage. L'enquête est confiée à la police judiciaire et en particulier au Commandant Marianne Dusseyre, mère du défunt petit ami de Sophie Mournel, qui soupçonne d'abord son ex-belle fille. Mais l'enquête s'intéresse rapidement vers la légende de la 13e note, d'origine égyptienne, à cause d'un tatouage sur le corps de la victime.", rank: 26, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres à Aix-en-Provence", length_in_mn: 90, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "La commandante Anne Giudicelli est chargée de l'enquête sur le meurtre d'un homme retrouvé crucifié dans la crypte de la cathédrale Saint-Sauveur d'Aix-en-Provence. Sur son corps, on retrouve un morceau de vieux parchemin ressemblant à une prophétie de Nostradamus. La sœur de l'enquêtrice est justement une grande historienne spécialisée dans la décryptage de ces prophéties. Malgré dix ans de brouille, les deux sœurs vont devoir collaborer alors que les meurtres se multiplient.", rank: 27, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres à Strasbourg", length_in_mn: 90, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Lors d'une dégustation de vin d'Alsace, sur le domaine du Clos-Mathis, on découvre du vin rosé et non blanc dans la cuve. On y retrouve le corps de Ronald Mathis, le père de Julian. Katel Leguennec, commandant du SRPJ de Strasbourg, mène l'enquête. Elle y travaille en collaboration avec Maxime Keller, patron du service medico-légal, récemment revenu de l'étranger. Ce dernier a été des années auparavant son amour de jeunesse et est désormais son beau-fils. D'autres meurtres s'ensuivent, qui semblent être liés à la légende de Sainte Odile, qui a un autel non loin et où un enfant a été abandonné deux décennies plus tôt.", rank: 28, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres à Narbonne/Le Secret de l'abbaye (HS08)", length_in_mn: 93, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Le corps d'un homme est retrouvé suspendu par les pieds dans le cimetière de Montjoyer. Alex Lazzari, un gendarme local, est chargé d'enquêter mais il doit faire équipe avec Alicia Tirard de la section de recherche de Grenoble. La collaboration commence mal : Alex a coincé le fils délinquant d'Alicia, peu de temps avant. Côté enquête, l'homme n'est pas directement identifié mais l'autopsie les amène à penser qu'il pourrait s'agir d'un moine de l'Abbaye Notre-Dame d'Aiguebelle, proche du cimetière. Le corps est en effet identifié : c'est le frère Yves. La congrégation produit une liqueur de plantes. La légende veut qu'un élixir d'immortalité soit à l'origine de la liqueur. La mort du religieux serait-elle liée à son activité au sein de l'abbaye ?", rank: 29, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres en Pays cathare", length_in_mn: 90, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Lors d'une visite touristique dans un château cathare, le corps d'une femme est découvert dans une cage de torture. Dépêchée sur les lieux, la lieutenante de gendarmerie Pauline Franchet, découvre sur place son propre frère, Victor. Trisomique et en état de choc, le jeune homme ne donne pas d'explication sur sa présence sur les lieux. Tout l'accuse. Pauline est déchargée de l'affaire et, Thomas Costella, un capitaine de la section de recherche de Montpellier, est chargé de l'enquête.", rank: 64, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres à Cayenne", length_in_mn: 90, year: 2020, is_recorded: true, is_seen: false, is_available: true, abstract: "Au pied du Fort Cépérou, à Cayenne, le corps d'un biologiste est retrouvé égorgé avec d'étranges signes sur le corps. La veille, il avait participé au bal des Touloulous. La capitaine Cassandra Molba et le lieutenant Antoine Lagarde sont chargés de l'enquête. Une quête de vérité qui fait face à la modernité et aux croyances guyanaises.", rank: 65, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres à La Rochefoucauld/Les Secrets du château (HS26)", length_in_mn: 90, year: 2020, is_recorded: true, is_seen: false, is_available: true, abstract: "Lors d'une fête au château de La Rochefoucauld, le beau-fils du duc et de la duchesse de L'Essile est assassiné à l'aide d'un peigne. Le commandant Alex Meurisse est chargé de l'enquête. Un retour et une enquête particulière pour lui puisqu'il a vécu au château et il a même vécu une histoire d'amour avec la femme de la victime. Les choses se corsent encore lorsqu'il apprend qu'il doit collaborer avec la duchesse de L'Essile, qui est également maire. Une enquête qui mêle légende et secrets de famille.", rank: 66, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres à Cognac", length_in_mn: 90, year: 2020, is_recorded: true, is_seen: false, is_available: true, abstract: "Clémentine Segonzac fait équipe avec Yassine Benjebbour, fraîchement muté de Marseille. Ils enquêtent sur le meurtre d'un maître de chai.", rank: 67, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres à Granville", length_in_mn: 90, year: 2021, is_recorded: false, is_seen: false, is_available: true, abstract: "Sur sa terrasse qui surplombe la mer à Granville, Camille Fauvel, ancienne médecin légiste et romancière à succès, écrit pour son nouveau roman une scène de meurtre très similaire à celle qui se déroule également sous nos yeux au même moment, sur la plage en contrebas. Après la découverte du cadavre, supplicié selon les anciens rites vikings, le lieutenant de police Damien Bonaventure est chargé de l'affaire. Nouvellement nommé dans la localité, il va trouver une alliée de poids en la personne très séduisante de l'écrivaine. Ensemble, et alors que le meurtrier se prépare à frapper de nouveau, Camille et Damien vont mettre à jour une étrange histoire de vengeance, venue du fond des âges et en rapport avec le passé de la ville.", rank: 68, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres à Albi", length_in_mn: 92, year: 2021, is_recorded: true, is_seen: false, is_available: true, abstract: "De retour à Albi, Annabelle Dalmasio doit faire équipe avec Marc Lemaire qui pensait recevoir à sa place la promotion de commissaire. Ils enquêtent sur le meurtre d'un fermier sur le corps duquel ont été gravés les mots « libro vitae » (au livre de vie en latin). Leurs recherches ainsi qu'un autre meurtre les mènent sur la piste d'un ancien adopté, et du centre d'adoption qui a placé des enfants contre leur intérêt.", rank: 69, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres à Pont-L'Évêque", length_in_mn: 90, year: 2021, is_recorded: true, is_seen: false, is_available: true, abstract: "Dans les années 50, la prison de Pont-l’Évêque fut surnommée la ""Joyeuse prison"". À cette époque, elle était devenue une sorte de prison folklorique sous la direction d'un gardien-chef qui préférait être aimé de ses détenus plutôt que d'être craint. En mémoire de cette histoire, le lieutenant de gendarmerie Julien Roussel, président de l'association ""Joyeuse prison"", a organisé une fête dans l'ancienne prison de Pont-L’Évêque pour nouer un dialogue entre le public, d'anciens détenus et le personnel pénitencier. Tous les invités sont déguisés comme dans les années 50, quand la prison était un lieu convivial et festif. Mais alors que la fête bat son plein, un homme vêtu d'une vieille tenue de prisonnier est retrouvé pendu dans la crypte de la prison. La victime n'est autre que le juge Daniel, 68 ans, héritier d'une grande famille de Pont-l’Évêque... Deux frères, que tout semble opposer, s'emparent de l'enquête.", rank: 70, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres à la Pointe du Raz", length_in_mn: 90, year: 2021, is_recorded: true, is_seen: false, is_available: true, abstract: "Le lieutenant de gendarmerie Jérémie Meyer, sur le point d'épouser Clara, fait équipe avec la commandante Marie Leroy venue le remplacer, pour enquêter sur le meurtre d'une vieille femme terrifiée par l'Ankou. Les pistes les mèneront sur la mort du père de Jérémie et sur celle d'une jeune fille qui a eu la vieille femme pour nourrice. La commandante Marie Leroy avait aussi une autre raison de venir.", rank: 71, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Fairies of Fryfam", french_title: "Les fées de Fryfam", length_in_mn: 90, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Agatha veut prendre l'air et se retirer au calme pour écrire un roman policier. Elle loue un cottage à Fryfam, un village où vivraient des fées. La détective n'a pas le temps de souffler qu'elle est déjà embauchée par Lucy qui veut prouver l'infidélité de son mari, Tolly. Mais ce dernier est retrouvé mort. Sa gorge a été tranchée. Crime passionnel ou cambriolage qui a mal tourné", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Curious Curate", french_title: "Un pasteur pas banal", length_in_mn: 90, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Tristan Delon, le nouveau pasteur de Carsely, plaît beaucoup aux paroissiennes, sauf à Sarah Bloxby, qui craint de voir le jeune séducteur évincer son mari retenu par sa mission en Afrique. Quand Tristan est retrouvé mort dans sa maison, elle est la première sur la liste des suspects.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Blacklist: Redemption", french_title: "Blacklist : Redemption", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "Susan Hargrave est la brillante et rusée chef de Grey Matters, une organisation secrète qui s'occupe des problèmes que le gouvernement n'ose pas toucher. Elle sera aidée de Tom Keen, son fils, qui deviendra son équipier.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Leland Bray", french_title: "Leland Bray", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Tom reprend du service chez Halcyon afin de retrouver Anna Copeland, agent de la CIA, et son fils, kidnappés par Leland Bray, lui-même ancien agent. En parallèle, Howard Hargrave, toujours vivant, prend contact avec son fils pour qu'il infiltre Halcyon Aegis afin de découvrir les mystère derrière sa tentative d'assassinat et la disparition de Christopher/Tom enfant.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Kevin Jensen", french_title: "Kevin Jensen", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Alors qu'il se trouve au Kurkystan pour un reportage sur des rumeurs de tortures et de repressions, Kevin Jenner, journaliste new-yorkais, est arrêté par les autorités du pays pour espionnage. Scottie, proche de Kevin et de sa famille, va monter une opération afin de le secourir avant qu'il ne soit trop tard.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Independence, U.S.A.", french_title: "La Mère patrie", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Suite à un crash d'avion commandité par le pentagone, Tom et Mathias sont envoyés en Russie pour infiltrer une mission internationale. Ils découvrent rapidement que l'avion, rempli de cadavres, a été crashé afin d'enquêter sur une base secrète russe qui s'avère être une reconstitution fidèle d'une petite ville américaine. Scottie, qui ignorait tout de cette opération conjointe du pentagone avec Halcyon, charge son assistante d'enquêter sur d'éventuelles autres informations que son mari aurait pu lui cacher.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Operation Davenport", french_title: "Opération Davenport", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Suite à une évasion d'une prison secrète de la CIA située dans New-York, Halcyon intervient à leur demande afin de retrouver les évadés le plus rapidement possible. Scottie découvre que Christopher a été placé à l'adoption une semaine après son enlèvement et confié aux Phelps sous le prénom de Jacob.", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Borealis 301", french_title: "Borealis 301", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Une équipe détourne des avions de ligne pour voler du matériel secrètement chargé à bord. Tom et Mathias se font passer pour des stewarts afin de découvrir ce qu'il en est. Halcyon découvre vite que les voleurs sont d'anciens SEALs déserteurs. Pendant ce temps, Howard demande à Tom de forcer le coffre de Scottie afin de trouver la clé d'un code capable de déchiffrer des messages codés au sujet de WhiteHall.", rank: 5, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Hostages", french_title: "Les Otages", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Tom demande l'aide de Nez afin de sauver Howard, fait prisonnier par Solomon pour le compte de Scottie. Halcyon est contacté par la compagnie d'assurance Carthay afin de monter une opération de secours pour ramener un chef d'entreprise kidnappé avec sa femme et son fils de 9 ans.", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Whitehall", french_title: "Whitehall, partie 1", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Scottie a découvert que Tom et Christopher ne sont qu'une seule et même personne. Après l'avoir fait interroger par Matias Solomon pour découvrir ce qu'il sait, Scottie le poursuit lorsqu'il essaie de s'échapper. Comprenant qu'il ne peut pas faire confiance à sa mère, Tom réussit à s'enfuir et rejoint son père qui a pu se soustraire à la garde de l’hôpital où il était retenu prisonnier grâce à l'aide de Liz et Harold Cooper. Dés lors, la course pour savoir ce qu'est Whitehall est lancée.", rank: 7, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Whitehall: Conclusion", french_title: "Whitehall, partie 2", length_in_mn: 42, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "L'assistante de Scottie, Kat Carlson, erre dans les rues, blessée et tenant une clé usb. Douze heures plus tôt, Howard planifie l'évasion de Richard Whitehall avec l'aide de Tom et Nez en utilisant sa prise de contrôle de Haegis Alcyon comme écran de fumée.", rank: 8, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "One Named Peter", french_title: "Il s'appelait Peter", length_in_mn: 55, year: 2014, is_recorded: true, is_seen: false, is_available: true, abstract: "Le commissaire Gibson se rend compte qu’elle a peut-être mis la vie de Rose Stagg en danger en l’entraînant dans l’affaire. Afin de la protéger au mieux, Gibson intensifie les investigations alors que Paul Spector rôde toujours dans les rues de Belfast.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "It's Always Darkest", french_title: "Toujours plus sombre", length_in_mn: 55, year: 2014, is_recorded: true, is_seen: false, is_available: true, abstract: "Alors que Stella déploie une haute surveillance sur Spector et sa famille, le serial-killer continue de former Katie qui l’assiste dans ses crimes. Il parvient également à rentrer dans la chambre des enquêteurs, ce qui rend le jeu du chat et de la souris encore plus personnel. Pendant ce temps, Gibson partage un moment intime avec Reed Smith, mais également avec Burns, lorsque ce dernier essaye de l’embrasser.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Strangler", french_title: "Intrusion", length_in_mn: 55, year: 2014, is_recorded: true, is_seen: false, is_available: true, abstract: "Le commissaire Gibson décide d’envoyer ses équipes au domicile du suspect afin d’y installer micros et caméras de surveillance. L’opération ne se déroule pas comme prévu ... Alors que Katie continue de fournir un faux alibi pour l’étrangleur, Paul continue de la préparer à l’aider dans ses crimes. Le corps d’une jeune femme dont la description correspond avec Rose Stagg a été retrouvé...", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Fall", french_title: "La Chute", length_in_mn: 55, year: 2014, is_recorded: true, is_seen: false, is_available: true, abstract: "Le commissaire Gibson continue de surveiller les mouvements de Spector tandis que Burns rend visite à un prêtre destitué de ses fonctions, qui aurait pu être en contact avec le suspect. Alors que Katie tente de détruire les preuves, Spector se fait arrêter.", rank: 5, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "In Summation", french_title: "L'Affrontement", length_in_mn: 55, year: 2014, is_recorded: true, is_seen: false, is_available: true, abstract: "Après avoir suivi l’interrogatoire de Paul Spector, qui a été arrêté pour l’enlèvement de Rose Stagg et ses autres crimes, le commissaire Gibson et le plus grand sérial-killer de Belfast se retrouvent enfin face à face...", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Yao", length_in_mn: 103, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "À l'occasion d'un retour dans le pays de ses ancêtres pour la promotion de son livre, Seydou Tall, une vedette française d'origine sénégalaise, va s'attacher à un jeune garçon, Yao, ayant parcouru seul plus de 387 kilomètres pour obtenir de lui un simple autographe. C'est alors le début d'une plongée au cœur du pays, en forme de road movie. Seydou va accompagner le petit Yao jusqu'à son village, Kalaga. Il va aussi faire la rencontre de multiples figures du Sénégal et d'une femme, Gloria, avec laquelle il semble s'évader.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Dirty John", french_title: "Dirty John", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "Cette histoire vraie, narre les méfaits commis par John Meehan, escroc et sociopathe américain, de 1990 à 2016. Elle porte principalement sur la relation de Meehan avec la femme d’affaires Debra Newell qu’il a rencontrée via un site de rencontres, les conséquences que cette relation a sur la famille de Debra et la descente aux enfers de cette dernière.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Approachable Dreams", french_title: "Les Rêves accessibles", length_in_mn: 48, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "0", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Red Flags and Parades", french_title: "Premiers signaux d'alarme", length_in_mn: 45, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "0", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Remember It Was Me", french_title: "Souviens-toi que ça vient de moi", length_in_mn: 45, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "0", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Shrapnel", french_title: "La Grenade", length_in_mn: 50, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "0", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Lord High Executioner", french_title: "Le Seigneur grand exécuteur", length_in_mn: 50, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "0", rank: 5, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "One Shoe", french_title: "Une chaussure", length_in_mn: 50, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "0", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Chivalry", french_title: "Chivalry", length_in_mn: 50, year: 2018, is_recorded: false, is_seen: false, is_available: true, abstract: "0", rank: 7, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "This Young Woman Fought Like Hell", french_title: "This Young Woman Fought Like Hell", length_in_mn: 50, year: 2018, is_recorded: false, is_seen: false, is_available: true, abstract: "0", rank: 8, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Gold Digger", french_title: "Le Doute", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "Une femme très riche tombe amoureuse d'un homme beaucoup plus jeune qu'elle. Quelles sont les conséquences que cette relation va avoir sur sa famille, à l’équilibre déjà fragile ?", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Son fils", length_in_mn: 55, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Julia et Benjamin se rencontrent totalement par hasard et entament une histoire d'amour passionnée, malgré la différence d'âge. Benjamin a en effet 25 ans de moins que Julia. Quand celle-ci présente son nouvel amour à ses enfants, ces derniers se posent aussitôt des questions sur son honnêteté...", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Sa fille", length_in_mn: 53, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Julia emmène Benjamin dans le Devon. Celui-ci découvre alors l'étendue qu'elle est plus riche qu'il ne l'avait imaginé. Une dispute éclate avec Ted, qui s'interroge sur les motivations de Julia et celles de Benjamin...", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Sa rivale", length_in_mn: 53, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "La relation entre Julia et Benjamin est mise en danger quand les enfants accusent ce dernier d'infidélité, mais ils décident tout de même d'emménager ensemble et Benjamin a encore une surprise pour sa dulcinée. Il lui fait sa demande en mariage. Tous deux sont convaincus de la force de leurs sentiments...", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "À l'intérieur", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: false, abstract: "Une jeune femme, Ana Galmont, est retrouvée assassinée, le cœur arraché, dans la clinique psychiatrique où elle avait été internée contre sa volonté, et d'où elle devait sortir le lendemain. Le lieutenant de police Angèle Maury, qui débute à la PJ, va devoir faire ses premiers pas d'enquêtrice en sondant les esprits réellement ou peut-être faussement troublés des patients de l'établissement.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "À Agnès D.", length_in_mn: 52, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Un assassinat a été commis dans une clinique psychiatrique. La victime, Ana, une jeune femme, avait été internée contre son gré et devait sortir le lendemain du crime. Angèle, jeune et brillante inspectrice de police de 29 ans, est chargée de mener cette enquête seule. La jeune femme, pour qui il s'agit de la première investigation, se demande comment elle va procéder pour interroger ces gens considérés comme «fous» et surtout quel crédit elle peut leur apporter. A-t-elle affaire au crime d'un fou ou à celui d'un tueur lucide qui s'applique à le faire passer pour l'acte d'un dément ?", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Ariane", length_in_mn: 52, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Alors qu'elle enquête sur le meurtre d'Ana, Angèle découvre un élément troublant de gémellité. La victime est, en effet, née le même jour et la même année qu'elle. Par ailleurs, le rapport d'autopsie révèle qu'Ana aurait eu un rapport sexuel consenti avant de mourir. Camille, une autre patiente qui souffre de dépression, est enceinte alors qu'elle ne se souvient pas avoir eu le moindre rapport. Angèle tente de démêler l'affaire et s'interroge sur la possibilité d'un lien entre les deux évènements. La jeune inspectrice de police est totalement obsédée par l'enquête au détriment de sa vie privée...", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Maxime", length_in_mn: 52, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Angèle a enfin trouvé le journal intime d’Ana et est persuadée que la vérité s’y cache. Mais le journal ayant séjourné dans l’eau, il est aux trois quarts illisible. Il va lui falloir du temps pour le déchiffrer. Les patients sont de plus en plus agités, ils ont peur que l’assassin ne recommence. Rosa, la voyante, l’a prédit, mais Angèle ne sait plus qui croire. Déjà troublée par Ana qui ne cesse de lui apparaître, elle est aussi déstabilisée par le beau Simon, un patient schizophrène au charme dévastateur, qui a tenté de l’embrasser.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Rose", length_in_mn: 52, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Maxime, le jeune fils de famille arrogant, est dans le coma, assommé par Bastien alors qu’il allait donner le nom de l’assassin à Angèle. Seule Rose, la voyante, pourrait maintenant aider Angèle, car elle sait des choses, Angèle en est sûre. Mais Rose s’est mise elle-même à l’isolement et personne n’a le droit de l’approcher. Si Angèle veut avancer, il va lui falloir passer outre. De plus en plus obsédée par Ana, totalement fascinée par Simon dont elle commence à tomber amoureuse, Angèle commence à basculer dangereusement de « l’autre côté ».", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Simon", length_in_mn: 52, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Maxime est sorti du coma. Il a donné le nom de l’assassin et Angèle, sous le choc, décide de ne pas le révéler au commissaire Favard. Maxime ment, elle en est persuadée, il ne peut pas en être autrement. Mais a-t-elle encore toute sa lucidité ? Son entourage commence à se poser des questions. Favard découvre bientôt qu’Angèle lui a caché la vérité et la jeune enquêtrice est mise à pied, virée de l’enquête et remplacée par David.", rank: 5, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Ana", length_in_mn: 52, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "La mère d’Angèle a persuadé Bastien qu’Angèle était en train de perdre la tête et qu’il fallait l’interner avant qu’il ne soit trop tard. Mais Angèle a réussi à s’enfuir avant qu’ils n’arrivent et, certaine d’avoir enfin trouvé le coupable, elle convainc Favard de reprendre des fouilles dans la clinique, et notamment dans le potager où ils trouvent enfin ce qu’ils cherchaient depuis le premier jour : le cœur d’Ana.", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Liés pour la vie", length_in_mn: 100, year: 2020, is_recorded: true, is_seen: false, is_available: true, abstract: "Lucie, championne d'équitation, a encore un rêve inachevé : décrocher un titre aux Jeux Olympiques. Elle sait qu'à son âge, les prochains JO sont sa dernière chance. Cela fait des années qu'elle s'entraîne et elle se sent prête. Mais à quelques mois de la compétition, le rêve tourne au cauchemar. Lucie est renversée par un chauffard. Le verdict est sans appel : ses jambes resteront paralysées. Pour Lucie, sportive accomplie, c'est la descente aux enfers. De la relation privilégiée avec son père, son amitié avec Léa, ses rêves de médailles, mais surtout son incroyable complicité avec Saphir, son cheval, Lucie va lentement tout perdre...", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Péril en la demeure", length_in_mn: 100, year: 1985, is_recorded: true, is_seen: false, is_available: true, abstract: "David Aurphet, un professeur de guitare vaguement paumé, est sollicité pour donner des cours à Viviane Tombsthay, la fille d'un couple très aisé. Julia la mère de Viviane, tombe immédiatement sous le charme de David et le poursuit de ses assiduités jusque chez lui. Il succombe facilement. Le couple semble vivre un adultère banal et régulier lorsque David reçoit par la poste une cassette vidéo où sont enregistrés ses ébats intimes avec Julia depuis un immeuble voisin.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Mensah, reine éléphante", length_in_mn: 52, year: 2014, is_recorded: true, is_seen: false, is_available: true, abstract: "Après la mort tragique de sa mère, la vieille matriarche, Mensah sait que c'est à elle que revient la tâche de mener le troupeau et son jeune éléphanteau en sécurité. Un voyage qui va les conduire à travers le désert aride, les marécages boueux et la vallée poussiéreuse, et jusqu'à leurs anciennes terres de pâture. Ce chemin, gravé dans la mémoire des éléphants femelles dès leur plus jeune âge, se transmet de mère en fille depuis des générations.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Bankable", length_in_mn: 86, year: 2012, is_recorded: true, is_seen: true, is_available: false, abstract: "En pleine crise financière, Philippe Deville, consultant financier perd son emploi et son train de vie fastueux quand Leslie Ricci, coiffeuse, monte sa boite de publicité sur internet...", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "影武者", french_title: "Kagemusha, l'Ombre du guerrier", length_in_mn: 160, year: 1980, is_recorded: true, is_seen: false, is_available: true, abstract: "Au XVIe siècle, le Japon est en proie à des guerres incessantes entre les clans. Le clan Takeda fait partie des plus puissants. Son chef charismatique, Takeda Shingen, rêve de prendre Kyoto et de s'emparer ainsi de tout le pays. Mais il est mortellement blessé avant de parvenir à ses fins, lors du siège du château de Noda. Pour protéger le clan, il ordonne alors à ses vassaux de dissimuler sa mort pendant une durée de trois ans. Le frère de Shingen qui, à l'occasion, lui servait de doublure, met la main sur un sosie parfait. Celui-ci n'a cependant pas l'étoffe de Shingen et chacun s'inquiète de le voir démasqué. Lui qui n'est qu'un voleur sans envergure, devra braver les intrigues, tromper l'entourage de Shingen et défendre le territoire des Takeda.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 4", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The ABC Murders", french_title: "A.B.C. contre Poirot", length_in_mn: 100, year: 1992, is_recorded: true, is_seen: false, is_available: true, abstract: "Hastings est de retour en Angleterre après une longue absence. Poirot lui montre la lettre de défi d'un certain ABC qui lui donne rendez-vous à Andover le 21 du mois. Poirot craint le pire et en effet, Mrs Ascher est retrouvée assassinée dans cette ville. S'ensuit une correspondance des plus macabres où le meurtrier indique chaque fois à Poirot le lieu et la date du prochain crime. Il semble que les meurtres aient lieu dans l'ordre alphabétique : Ascher à Andover, Barnard à Bexhill... Et chaque fois l'assassin laisse sur les lieux du crime un guide des chemins de fer ABC. La police recherche un fou, mais pour Poirot c'est l’œuvre de quelqu'un de bien plus méthodique.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Death in the Clouds", french_title: "La Mort dans les nuages", length_in_mn: 100, year: 1992, is_recorded: true, is_seen: false, is_available: true, abstract: "Dans un avion qui le ramène vers l'Angleterre après un séjour à Paris, Poirot s'endort. Bien dommage pour lui car pendant son sommeil Mme Giselle est tuée par un dard empoisonné. La victime était une femme qui avait beaucoup d'ennemis, les suspects ne manquent donc pas, même parmi les passagers: Lady Horbury (que la victime faisait chanter), Daniel Clancy (qui possède une sarbacane susceptible d'avoir été utilisée). Aidée de Jane Grey, l’hôtesse de l'air, Poirot va avoir du travail pour trouver le meurtrier...", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "One, Two, Buckle My Shoe", french_title: "Un, deux, trois...", length_in_mn: 100, year: 1992, is_recorded: false, is_seen: false, is_available: true, abstract: "Tout comme le commun des mortels, Hercule Poirot n'aime pas son dentiste. Mais apparemment quelqu'un l'aime encore moins puisqu'il meurt d'une balle dans la tête peu de temps après avoir soigné l'éminent détective et un banquier très influent, Alistair Blunt. Il se révélera qu'il avait commis une erreur mortelle pour un de ses patients le jour même de sa mort ce qui rend l'hypothèse du suicide très probable. Mais pour Poirot, qui ne se contente jamais d'une solution simple, il s'agit d'un meurtre. D'autres événements le prouveront par la suite ...", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 5", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 5, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Adventure of the Egyptian Tomb", french_title: "La Malédiction du tombeau égyptien", length_in_mn: 50, year: 1993, is_recorded: true, is_seen: false, is_available: true, abstract: "Lors de l'ouverture d'un tombeau égyptien de la Vallée des Rois, Sir John Willard meurt soudainement. Sa veuve n'est pas convaincue de sa mort naturelle et fait appel à Hercule Poirot avant de revenir sur sa décision. Cependant, dans les jours qui suivent, les membres de l'expédition commencent à mourir les uns après les autres. Poirot part alors en Égypte avec Hastings se confronter à la « malédiction du pharaon » ...", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Underdog", french_title: "L'Affaire de l'invention volée", length_in_mn: 50, year: 1993, is_recorded: false, is_seen: false, is_available: true, abstract: "Hastings part rejoindre un ami, Charles, pour une partie de golf. Poirot l'accompagne car ils sont invités ensuite chez l'oncle de Charles, Sir Reubens, PDG d'une entreprise de chimie, qui possède la plus belle collection de miniatures belges en bronze. Poirot et Hastings s'aperçoivent que leur hôte est détesté de tous et ils ne sont pas surpris lorsque le lendemain il est retrouvé mort dans son bureau. Entre affaires privées et secrets industriels, Poirot ne manque pas de suspects...", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Yellow Iris", french_title: "L'Iris jaune", length_in_mn: 50, year: 1993, is_recorded: false, is_seen: false, is_available: true, abstract: "Il y a deux ans, sur le chemin pour voir Hastings en Argentine, Poirot n'avait pas pu enquêter sur la mort de Iris Russel. Il avait été expatrié de force par l'armée, suspecté d'espionnage. Aujourd'hui, il reçoit un iris jaune alors que le même restaurant qu'en Argentine ouvre à Londres. Grâce à un dîner de commémoration organisé par le mari, Poirot a l'occasion de pouvoir trouver le meurtrier, bien décidé à ne pas le laisser s'échapper cette fois-ci...", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Case of the Missing Will", french_title: "L'Affaire du testament disparu", length_in_mn: 50, year: 1993, is_recorded: false, is_seen: false, is_available: true, abstract: "Il y a 10 ans, Andrew Marsh annonçait le contenu de son testament dont un des points importants était que, dans sa misogynie, il ne laissait rien à sa pupille, Violet. Aujourd'hui, fier de ce qu'elle est devenue, il change d'avis et veut faire d'elle son unique héritière. Un soir, il fait part à Poirot de son souhait ainsi que celui de faire de lui son exécuteur testamentaire. Mais il est tué avant d'avoir pu faire la modification testamentaire...", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Adventure of the Italian Nobleman", french_title: "Un dîner peu ordinaire", length_in_mn: 50, year: 1993, is_recorded: false, is_seen: false, is_available: true, abstract: "Poirot et Hastings enquêtent sur le meurtre du comte Foscatini. Miss Lemon est déjà sortie avec son valet, M. Graves, qui s'est fait passer pour son secrétaire personnel. Il indique à Poirot que son maître traitait des affaires importantes pour le gouvernement italien, ce que l'ambassade d'Italie nie formellement. Poirot les suspecte de mentir ; d'ailleurs il semble y avoir beaucoup de secrets dans cette affaire...", rank: 5, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Chocolate Box", french_title: "La Boîte de chocolats", length_in_mn: 50, year: 1993, is_recorded: false, is_seen: false, is_available: true, abstract: "Hercule Poirot accompagne à Bruxelles l'inspecteur Japp qui doit être fait Compagnon de la Branche d'Or. Ils rencontrent un ancien collègue de Poirot du temps où il était encore policier, le commissaire Claude Chantalier. Ensemble, ils évoquent une affaire de 20 ans, la première enquête de Poirot en tant que détective : Paul De Roulard, un ministre belge soupçonné de collaborer avec les Allemands, est retrouvé mort dans son bureau. Le malheureux aurait succombé à une crise cardiaque selon le rapport de la police belge. Mais bien sûr ni Poirot, ni Virginie,la cousine de De Roulard, ne croient à la théorie de l'attaque cardiaque...", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Dead Man's Mirror", french_title: "Le Miroir du mort", length_in_mn: 50, year: 1993, is_recorded: false, is_seen: false, is_available: true, abstract: "Poirot est à une vente aux enchères pour acheter un miroir qui irait très bien dans son vestibule, cependant c'est un collectionneur, Gervase Chevenix, qui remporte l'enchère. Chevenix demande à Poirot de venir enquêter chez lui en échange du miroir. Il pense être victime d'une arnaque par son associé. Poirot, malgré l'impolitesse et l'air supérieur de Chevenix, décide d'accepter l'invitation. À son arrivée, la femme de Chevenix confie à Poirot qu'un esprit lui a dit que la mort est imminente pour un membre de son entourage…", rank: 7, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Jewel Robbery at the Grand Metropolitan", french_title: "Vol de bijoux à l'Hôtel Métropole", length_in_mn: 50, year: 1993, is_recorded: false, is_seen: false, is_available: true, abstract: "Sur les conseils de son médecin, Hercule Poirot va se reposer à l'Hôtel Métropole de Brighton. Lors de son séjour, il se rend à une pièce de théâtre où l'actrice principale, Margaret Opalsen, porte un magnifique collier de perles, cadeau d'un tsar russe à une danseuse. Mais le soir même, le collier de perles est volé. Ed Opalsen, le producteur de la pièce, demande à Poirot d’enquêter mais celui-ci répond qu'il est en vacances. Cependant, Poirot est sans arrêt ennuyé à cause du jeu d'un journal local. Quitte à être dérangé, il décide de s'occuper de l'affaire...", rank: 8, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le Nom des gens", length_in_mn: 100, year: 2010, is_recorded: true, is_seen: false, is_available: true, abstract: "Bahia Benmahmoud est une pasionaria des temps modernes. Adepte de la méthode baba cool, elle fait l’amour plutôt que la guerre et couche avec les hommes de droite qu'elle croise pour les faire changer d'opinion, se définissant elle-même comme une « pute politique ». Cette méthode porte ses fruits jusqu'au jour où elle rencontre Arthur Martin, qu'elle classe immédiatement comme un fasciste potentiel en raison de son discours sur le principe de précaution et la grippe aviaire, qu'elle qualifie de paranoïaque, mais aussi de son homonymie avec un fabricant d’électroménager. Elle réalise néanmoins son manque de discernement (Arthur est socialiste et grand fan de Lionel Jospin) et se rend compte progressivement qu'elle est attirée par lui.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Démocraties animales", length_in_mn: nil, year: 2021, is_recorded: false, is_seen: false, is_available: false, abstract: "Au cœur de somptueuses réserves animalières, la découverte d’espèces qui prennent collectivement et démocratiquement leurs décisions.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le peuple gouverne", length_in_mn: 43, year: 2021, is_recorded: true, is_seen: true, is_available: false, abstract: "Ce premier volet part à la rencontre d’espèces animales européennes composées de dizaines, centaines, voire milliers d’individus, tous consultés lorsqu’il s’agit de prendre des décisions pour la communauté.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le chef consulte", length_in_mn: 43, year: 2021, is_recorded: true, is_seen: true, is_available: false, abstract: "Chez les babouins, l’autorité du dominant a des limites puisque celui-ci est capable de se plier à la décision de ses congénères lorsqu’il s’agit, notamment, de choisir la direction vers laquelle aller.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Tamara", length_in_mn: 103, year: 2016, is_recorded: true, is_seen: true, is_available: false, abstract: "Cette adaptation de la BD du même nom retrace une période de la vie d'une jeune fille complexée par ses rondeurs. Elle tombe amoureuse du garçon qui fait craquer toutes les filles du lycée. Une aventure naît entre eux, sous des regards moqueurs et malveillants. Le quotidien de ces adolescents, rythmé par leurs amours, familles, amis, disputes...", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "J'ai épousé un inconnu", length_in_mn: 90, year: 2015, is_recorded: true, is_seen: false, is_available: true, abstract: "Jeune psychiatre douée exerçant dans un centre pour adolescents perturbés, riche héritière, Emma épouse David, rencontré six mois plus tôt, meilleur ami de son collègue psychiatre, Aurélien, dont la femme s'est suicidée. David emmène Emma dans une maison où il dit n'être pas allé depuis des années, perdue dans la nature. Il sort couper du bois, la nuit tombe, panne d'électricité, Emma erre dans la maison, appelle son mari, une ombre cagoulée surgit, une hache à la main et agresse Emma. Un chasseur se porte à son secours mais est tué. L'agresseur s'enfuit. À partir de là, la police, ses parents, les omissions et mensonges de David, la disparition d'une infirmière chargée de veiller sur elle vont amener Emma à soupçonner son mari. Elle subit une autre agression mystérieuse mais est aussi menacée par le père d'une de ses jeunes patientes décédée.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 7", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 7, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "3 Godfathers", french_title: "Le Fils du désert", length_in_mn: 106, year: 1948, is_recorded: true, is_seen: false, is_available: true, abstract: "Trois bandits, Robert Hightower, William dit « Abilene Kid » et Pedro, attaquent une banque d'une petite ville de l'Arizona. Traqués par le shérif de la ville, ils doivent s'enfuir dans le désert à cheval. Lors d'une tempête de sable, ils perdent leurs chevaux. À ce moment, leur unique chance de salut est de se rendre à un point d'eau à pied.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Mussolini-Hitler, l'opéra des assassins", length_in_mn: 96, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Benito Mussolini et Adolf Hitler étaient deux dictateurs que tout semblait opposer, bien que guidés par la même idéologie fasciste et fanatique. Les trajectoires des deux despotes, tout d'abord communes, se sont écartées au fil des années, jusqu'à devenir conflictuelles et dramatiques. Des images d'archives, mêlant grande histoire et vie privée, et privilégiant le point de vue de Mussolini, permettent de retracer l'histoire de ces dictateurs et leurs relations pour le moins singulières. A travers ces rapports complexes se révèlent également certains aspects méconnus de la Seconde Guerre mondiale.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Walk of Shame", french_title: "Blackout total", length_in_mn: 95, year: 2014, is_recorded: true, is_seen: true, is_available: false, abstract: "À la suite d'une soirée agitée, Meghan Miles (Elizabeth Banks), présentatrice du journal télévisé sur une chaîne locale, se retrouve perdue en plein Los Angeles, sans argent ni téléphone ni voiture, à peine quelques heures avant le tournage d'une émission censée servir de tremplin à sa carrière.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Arsène Lupin (Descrières)", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "Cette série met en scène les exploits du célèbre gentleman-cambrioleur.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 1", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 2", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le Bouchon de cristal", length_in_mn: 55, year: 1971, is_recorded: true, is_seen: false, is_available: true, abstract: "Avec deux de ses complices, Arsène Lupin se trouve dans une villa cossue d'Enghien-les-Bains, dans la région parisienne, villa qui appartient au député Daubrecq. Après avoir ouvert un coffre-fort, il y dérobe « le plus beau [tableau] des primitifs flamands », un triptyque volé à Béthune par les Allemands pendant la Grande Guerre et qu'on pensait avoir été emporté en Allemagne par le Kronprinz. Soudain, le maître d'hôtel Léonard est assassiné. La police arrive sur les lieux et arrête les deux complices de Lupin, Gilbert et Sebastiani : l'un est innocent, l'autre coupable. Pourquoi Gilbert l'a-t-il poussé à cambrioler la villa d'Enghien et le bouchon de cristal ? Sa mission : sauver son « complice » Gilbert.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Victor, de la Brigade mondaine", length_in_mn: 55, year: 1971, is_recorded: true, is_seen: false, is_available: true, abstract: "Des coups de feu sont échangés entre des policiers et des malfaiteurs, qui viennent de dévaliser une banque. Le commissaire Guerchard est chargé de l'affaire. Une évidence selon lui : le coup a été commis par Arsène Lupin en personne ! Le préfet de police a un plan : faire croire que l'enquête est toujours menée par Guerchard, alors qu'elle est confiée en secret à un policier d'envergure que Lupin ne connaît pas. L'homme en question se nomme Victor, de la Brigade mondaine.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Arsene Lupin contre Herlock Sholmes", length_in_mn: 55, year: 1971, is_recorded: true, is_seen: false, is_available: true, abstract: "Dautrec, un riche banquier, très antipathique et abusant de son pouvoir, surtout auprès des femmes, est retrouvé assassiné, chez lui, peu de temps après avoir acheté un diamant royal d'une valeur inestimable. Le préfet de police fait appel à Herlock Sholmes et son adjoint pour résoudre cette énigme. Le détective anglais reconnaît sous les traits de l'expert en diamants et du jeune et brillant Maxime Bermond, Arsène Lupin. Il se fait fort de l'arrêter, lui et sa complice Natacha, et de retrouver le diamant. Mais c'est sans compter sur l'intelligence d'Arsène Lupin.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "L'Arrestation d'Arsène Lupin", length_in_mn: 55, year: 1971, is_recorded: true, is_seen: false, is_available: true, abstract: "Se faisant passer pour Bernard d'Andrézy, Arsène Lupin se rend à une réception chez Gournay-Martin, le richissime propriétaire d'une marque de champagne. Tout le monde visite les caves et Lupin fait d'étranges marques à la craie le long des murs. Cela attire l'attention d'un des invités, et quand un télégramme annonce la présence d'Arsène Lupin dans l'assistance, le gentleman-cambrioleur ne tarde pas à être poursuivi et arrêté. C'est son vieil ennemi Guerchard qui lui passe les menottes et fait annoncer la nouvelle de l'arrestation. Combien de temps durera son triomphe ?", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "L'Agence Barnett", length_in_mn: 55, year: 1971, is_recorded: true, is_seen: false, is_available: true, abstract: "(1re partie) Le curé d'un petit village surprend dans son église un cambrioleur qui réussit à s'échapper. Le détective privé Jim Barnett s'intéresse à cette affaire, d'autant plus que l'inspecteur Béchoux le soupçonne, non seulement d'être l'auteur du vol mais aussi de cacher sous son personnage de Barnett sa véritable identité, celle d'Arsène Lupin. Barnett aura vite fait de résoudre l'enquête en ridiculisant Béchoux et en confondant le baron de Gravières, faux manchot et vrai coupable. (2e partie) À Paris, un notaire maître Gassire vient de se faire voler une importante liasse de titres. Béchoux, chargé de l'enquête est amené à fouiller l'appartement de son ex-femme Olga, voisine du notaire. Celle-ci, furieuse, lui rend ses lettres d'amour. Barnett, à la demande du notaire, cherche lui aussi l'auteur du vol, en faisant la cour à deux ravissantes jeunes femmes de l'immeuble, une flûtiste et une dactylographe. Béchoux finit par arrêter Barnett et le conduit devant le divisionnaire Guerchard, l'accusant, sans preuve, d'être Arsène Lupin. Ce dernier ne trouvera son salut qu'en révélant où sont cachés les titres, dans le cartable même de Béchoux, au milieu des lettres d'amour d'Olga.", rank: 5, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "La Demoiselle aux yeux verts", length_in_mn: 55, year: 1971, is_recorded: true, is_seen: false, is_available: true, abstract: "Au casino de Baden Baden, Arsène Lupin rencontre une ravissante anglaise Dora. Celle-ci, le reconnaissant, se fait une gloire de lui voler son portefeuille. Intrigué, il décide de la suivre dans le train. Au cours de ce voyage, ils sont attaqués et Arsène Lupin retrouve une jeune fille aux yeux verts, rapidement aperçue à Baden Baden. Cette dernière est soupçonnée de meurtre par le commissaire au monocle Marshall. Arsène Lupin, toujours prêt à défendre l'innocence, surtout quand elle est jolie, découvrira que la jeune fille Aurélia est, en réalité, victime de son tuteur. Ce dernier, aidé de complices et prêt à tout pour récupérer l'héritage, voulait l'épouser. Arsène Lupin, qui dans cet épisode, est à la fois, comte, lord et accordeur de piano, libérera la jeune fille de son tuteur et de son prétendu jeune amoureux, et lui fera récupérer la fortune que son père, ingénieur astucieux, avait si bien cachée.", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "La Chaîne brisée", length_in_mn: 55, year: 1971, is_recorded: true, is_seen: false, is_available: true, abstract: "Dans le port d'Amsterdam, on retrouve dans une malle un homme drogué et des documents scientifiques, ultra-secrets. Les autorités font appel à Arsène Lupin pour trouver l'origine des fuites et démanteler l'organisation qui en bénéficie. Lupin se lie avec deux jeunes femmes, membres de l'organisation, la brune Hélène et la blonde Claudia et réussit, en se faisant passer pour un perceur de coffre-fort à se mettre en rapport avec le chef du réseau, un conservateur de musée. Celui-ci le démasque et Arsène Lupin doit la vie sauve à Hélène. Ensemble, ils découvrent, dans le sous-sol du musée, caché dans un sarcophage de momie pour fuir, le cerveau de l'organisation, qui n'était autre que le directeur de la recherche scientifique.", rank: 7, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "La Femme aux deux sourires", length_in_mn: 55, year: 1971, is_recorded: false, is_seen: false, is_available: true, abstract: "Arsène Lupin arrive à Rome sous 2 identités différentes, celle d'un banquier et celle d'un artiste peintre. Avec l'aide de son fidèle Grognard, il va résoudre une histoire de famille et de chantage. Le célèbre voleur Peppino fait chanter le marquis Valbrona. Il lui réclame les bijoux de sa femme Rosa, une cantatrice disparue brutalement, avant de lui rendre sa fille Clara, que le marquis a eu avec Rosa mais que Peppino avait enlevée pour en faire sa complice. L'affaire s'embrouille quand une autre jeune fille blonde apparaît qui prétend s'appeler Antonina. Le commissaire Gorgone devient fou. Mais Arsène Lupin finit par comprendre que Rosa avait eu des jumelles. Il retrouve les bijoux qu'il rendra au Marquis, tous sauf le plus beau des colliers.", rank: 8, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "La Chimère du calife", length_in_mn: 55, year: 1971, is_recorded: true, is_seen: false, is_available: true, abstract: "Dès leur arrivée à Ungoldingen, Fox, le célèbre détective londonien et son ami Robertson se rendent chez le baron von Augstadt, victime d'un vol de bijou, une chimère. Tandis que le baron leur raconte les circonstances du vol, la baronne a un rendez-vous secret dans un musée avec Arsène Lupin. Elle lui confie qu'elle est victime d'un chantage de la part du docteur Brade. Celui-ci considère la chimère comme un atout dans les négociations entre sa société de pétrole, concurrente de celle du baron, et l'émir du Sudrat qui possède des champs pétrolifères. Cette enquête met au jour la rivalité existante entre Arsène Lupin et le détective anglais Fox et montre combien pour Arsène Lupin, défendre l'honneur d'une dame passe avant tout.", rank: 9, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Une femme contre Arsène Lupin", length_in_mn: 55, year: 1971, is_recorded: true, is_seen: false, is_available: true, abstract: "Un gang de voleurs de bijoux écume la riche ville de St Moritz. Les bijoux sont d'abord photographiés puis on en fait des copies que l'on substitue ensuite aux vrais bijoux volés. Une jeune femme, victime du krach boursier et désirant vendre ses diamants qui ne sont plus que des faux, met à jour l'escroquerie. De plus, la photographe impliquée dans l'affaire est assassinée. Quelques mois plus tard, la police étant impuissante, les compagnies d'assurance font appel à Arsène Lupin. Mais humilié par des articles d'une jeune journaliste Maria Bonetti le sous-estimant, Arsène Lupin redouble d'ardeur et de ruse. Le meilleur moyen de se venger, c'est de sauver Maria Bonetti que l'on tente de tuer.", rank: 10, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Les Anneaux de Cagliostro", length_in_mn: 55, year: 1971, is_recorded: true, is_seen: false, is_available: true, abstract: "Un congrès de la science des trésors attirent à Vienne Arsène Lupin déguisé en vicomte Raoul d'Andrézy, sa rivale de toujours la comtesse Tamara, une jeune journaliste Georgina Neydegg et un célèbre professeur irlandais Corcoran qui doit faire une conférence sur le trésor de Cagliostro. Tout ce monde se réunit chez le baron et la baronne Ordosczy. Dans son exposé, Corcoran révèle que les mystérieuses inscriptions gravées sur les sept anneaux recèlent le secret du trésor. Au moment où il présente les anneaux à l'assistance, la lumière s'éteint. Seul un éclair de magnésium produit par l'appareil photo troue l'obscurité. Quand la lumière revient, les anneaux ont disparu et la plaque photographique aussi. Chacun se met à la recherche des anneaux originaux afin de déchiffrer les inscriptions et de retrouver le trésor.", rank: 11, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Les Tableaux de Tornbüll", length_in_mn: 55, year: 1971, is_recorded: true, is_seen: false, is_available: true, abstract: "Il y a tant de touristes l'été dans le château de Tornbüll que le comte Stefan, propriétaire d'une remarquable collection de tableaux, tremble à chaque visite. Comme tous les étés, il organise une petite fête, un bal masqué. Arsène Lupin, déguisé en romancier anglais infirme, Sir Alexander, est l'un des invités. Il est accompagné de Lady Bakefield. Sir Alexander conseille à Tornbüll de faire copier ses œuvres d'art et d'enfermer les originaux dans un coffre. Pour ce travail, il recommande au comte Gabriela, une jeune artiste. Deux hommes surveillent tout ce qui se passe. Ce sont les frères Forster, des redoutables gangsters qui décident de se faire passer pour une équipe de tournage de cinéma afin de subtiliser les tableaux. Ils n'avaient pas prévu que dans l'équipe les doublures n'étaient autre qu' Arsène Lupin et Lady Bakefield.", rank: 12, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le Sept de cœur", length_in_mn: 55, year: 1971, is_recorded: false, is_seen: false, is_available: true, abstract: "C'est dans cet épisode que Maurice Leblanc, alors journaliste venant d'acheter une maison à Bruxelles, fait la connaissance d'Arsène Lupin, un proche du précédent propriétaire de la maison, ingénieur en aéronautique mort et disparu dans des circonstances étranges. Maurice Leblanc est victime d'une visite nocturne d'un mystérieux inconnu venant fouiller dans sa nouvelle maison. Arsène Lupin, qu'il vient de rencontrer quelques jours auparavant sous le pseudonyme de Jean Daspry dans le cadre de son travail de journaliste, va aider son nouvel ami à résoudre l'affaire, et Maurice Leblanc deviendra le futur « biographe » d'Arsène Lupin, qui était déjà connu des polices européennes et de la population. Maurice Leblanc, journaliste, publiera alors en nouvelles les précédentes affaires d'Arsène Lupin et écrira des romans sur chacune des futures affaires de son ami. C'est une version de l'histoire qui est propre à la série télévisée, les véritables romans de Maurice Leblanc présentent une version quelque peu différente...", rank: 13, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "La Cage dorée", length_in_mn: 90, year: 2013, is_recorded: true, is_seen: true, is_available: false, abstract: "Maria et José Ribeiro, d'origine portugaise, vivent tranquillement à Paris, où ils ont élevé leurs deux enfants. Elle est concierge dans un immeuble bourgeois tandis que lui est chef de chantier dans une entreprise de construction. Tout le monde abuse de leur trop grande gentillesse. À la suite du décès du frère de José, avec qui ce dernier était fâché depuis longtemps, les époux Ribeiro apprennent qu'ils sont bénéficiaires d'un important héritage, dont une maison au Portugal. Mais il y a une condition dans le testament : s'installer au Portugal pour continuer à faire vivre l'entreprise familiale. Or, pour différentes raisons, certains proches et les employeurs de Maria et José ont tout intérêt à faire en sorte que ceux-ci restent à Paris. Ils vont alors tout imaginer pour les empêcher de partir.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le bonheur est dans le pré", length_in_mn: 106, year: 1995, is_recorded: true, is_seen: true, is_available: false, abstract: "Chef d'entreprise à Dole, dans le Jura, Francis Bergeade n'a pas une vie réjouissante. Les tracas s'accumulent tant qu'il finit par en faire un malaise vagal. Hospitalisé, c'est pendant sa convalescence que se produit l'imprévisible : une fermière, Dolorès Thivart, et ses deux filles, venues de Condom, dans le Gers, participent à une émission de télévision pour retrouver leur mari et père, un certain Michel Thivart, disparu vingt-six ans plus tôt. Il profite alors de son incroyable ressemblance avec Michel Thivart pour prendre sa place et fuir ses problèmes.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le Magnifique", length_in_mn: 95, year: 1973, is_recorded: true, is_seen: true, is_available: false, abstract: "Un écrivain timide s'est inventé un double littéraire, un agent secret qui possède la séduction et le courage qu'il n'a pas, et transforme les gens de son quotidien en personnages de roman.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Comme un mauvais souvenir", length_in_mn: 90, year: 2009, is_recorded: true, is_seen: false, is_available: true, abstract: "0", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Une sale journée", length_in_mn: 52, year: 2021, is_recorded: true, is_seen: false, is_available: true, abstract: "Luther est appelé à l’aide par le marchand d’art Eliott Carrodus, dont la femme Jessica est retenue en otage par un homme de sinistre réputation qui se fait appeler L'orpailleur. Celui-ci exige comme rançon sept diamants de grande valeur. Ce qu’il ignore, c’est que Jessica les a avalés pour mieux les cacher. Luther va devoir faire preuve de créativité pour tenter de la sauver…", rank: 5, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "De profundis", length_in_mn: 52, year: 2021, is_recorded: true, is_seen: false, is_available: true, abstract: "Luther est soupçonné d’un meurtre, ses empreintes sont sur l’arme du crime. Pourchassé, il a de plus en plus de mal à distinguer ses amis de ses ennemis. Et cela fait les affaires d’une alliée de circonstance bien spéciale…", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Demi-sœurs", length_in_mn: 105, year: 2018, is_recorded: true, is_seen: true, is_available: false, abstract: "Lauren, ravissante it-girl de 29 ans, tente de percer dans le milieu de la mode en écumant les soirées parisiennes. Olivia, 28 ans et un rien psychorigide, a deux obsessions : sauver la confiserie de ses parents et se trouver le mari idéal. À 26 ans Salma, jeune professeur d’histoire fougueuse, vit encore chez sa mère en banlieue. Elles ne se sont jamais rencontrées, jusqu’au jour où elles découvrent qu'elles sont demi-sœurs. Pour ces trois jeunes femmes qui n’ont rien en commun, la cohabitation promet d'être explosive.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Harcelés", length_in_mn: 90, year: 2020, is_recorded: true, is_seen: false, is_available: true, abstract: "Une famille, comme tant d'autres, va voir son quotidien bouleversé par des cyber attaques en rafales. La famille Vallorca survivra-t-elle aux révélations successives qui dévoileront leurs secrets les plus intimes ? En tentant de démasquer celui qui se cache derrière ces intrusions, Isabelle et Éric vont devoir être plus solides que jamais, et redoubler d'efforts quand leur fils Hugo se retrouvera en danger de mort…", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Son mari", length_in_mn: 57, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Julia parle à Ted de ses fiançailles avec Benjamin, ce qui entraîne des conséquences inattendues. Patrick tente de convaincre Julia de demander à son futur époux de signer un accord pour la protection de ses biens...", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Son bébé", length_in_mn: 57, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Avec l'arrivée du demi-frère de Benjamin, Julia devient suspicieuse et pense que ce dernier lui cache quelque chose. Ses doutes s'avérant fondés, elle commence à se poser des questions sur leur futur mariage...", rank: 5, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Son amour", length_in_mn: 55, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Lorsque le demi-frère de Benjamin refait surface Julia veut découvrir ce que cache son fiancé. Lorsqu'elle aura découvert son secret, voudra-t-elle toujours l'épouser ?...", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 6", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Meurtres au Havre (Les Fantômes du Havre) (HS15)", length_in_mn: 105, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Alors qu'un ouvrier s'affaire aux travaux d'embellissement d'un appartement du Havre, en démolissant le mur qui bouchait une cheminée désaffectée, il y découvre un cadavre momifié... Un duo d'inspecteurs va entreprendre de dénouer l'écheveau très compliqué de ce qui apparaît comme un crime nébuleux et sordide. Au tout début de l'enquête, la policière va découvrir que le médecin-légiste qui autopsie le cadavre n'est autre que son père qu'elle n'a pas vu depuis vingt ans ! Alors que l’appartement du crime, appartenant à une famille influente des environs, a brûlé après un départ de feu volontaire, l'autopsie révèle que la femme momifiée venait d’accoucher juste avant d’être emmurée.", rank: 43, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le ventre, notre deuxième cerveau", length_in_mn: 55, year: 2013, is_recorded: true, is_seen: false, is_available: true, abstract: "Que savons-nous de notre ventre, cet organe bourré de neurones, que les chercheurs commencent à peine à explorer ? Selon cette captivante enquête scientifique, il semblerait que notre cerveau ne soit pas le seul maître à bord.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Les lentilles : le remède à la faim dans le monde", length_in_mn: 53, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Nourrissante, bon marché et facile à cultiver, la lentille fait figure d’aliment providentiel. Cultivée aussi bien en Inde qu'en Éthiopie ou en Amérique du Nord, cette plante pourrait être un remède possible à la malnutrition.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Microbiote, les fabuleux pouvoirs du ventre", length_in_mn: 59, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Et si l’avenir de la médecine se jouait dans notre ventre ? Aux avant-postes de la recherche, cette nouvelle enquête des auteurs de ""Mâles en péril"" et ""Le jeûne, une nouvelle thérapie ?"" explore notre flore intestinale.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Noces d'or", length_in_mn: 93, year: 2019, is_recorded: true, is_seen: true, is_available: false, abstract: "Octave Saint-Cast, diplomate à la retraite, a invité du beau monde pour fêter ses noces d'or avec Alix, dans une somptueuse demeure, le château de La Rolandière. Atteinte de la maladie d'Alzheimer, Alix l'a pourtant quelque peu oublié. Mais lorsque sa fille Dora vient la chercher dans l'institut où elle est placée, elle a la surprise de la trouver dans les bras de Farhad, un patient iranien dont elle est tombée amoureuse. Le fils et la petite-fille de Farhad étant présents sur place, Dora emmène tout ce petit monde au château, au grand étonnement de la famille déjà sur place. Le vieux diplomate est autant inquiet pour sa femme que pour les invités de marque, parmi lesquels l'ancien président Valéry Giscard d'Estaing, qui doivent arriver le surlendemain.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Imposture", length_in_mn: 100, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Alors qu'elle est en mission dans le Grand Nord canadien, Alice Minville, jeune infirmière française installée au Québec depuis plusieurs années, apprend le décès de sa mère, Suzanne, victime d'un accident de voiture. Son père, Alexandre Caussey a fait rapatrier le corps à Aix-en-Provence à des fins d'inhumation. Mais pour Alice, son père est mort depuis 27 ans et il ne peut donc être à l'origine de cette démarche. Bien décidée à en savoir davantage, elle se rend aussitôt en France.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Les Blessures de l'île", length_in_mn: 90, year: 2015, is_recorded: true, is_seen: false, is_available: true, abstract: "Gregor Gourvennec, capitaine de gendarmerie né sur une île bretonne, retourne sur les lieux de son enfance pour résoudre un meurtre commis dans une maison abandonnée. Sur place, il se voit confronté à un événement dramatique qui a eu lieu dans sa jeunesse. Il est accompagné par Manon Le Gall, nettoyeuse de scènes de crime et future neurochirurgienne. Elle profite de son passage sur l'île pour faire la lumière sur son passé dont elle n'a aucun souvenir...", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Changeling", french_title: "L'Échange", length_in_mn: 141, year: 2008, is_recorded: true, is_seen: false, is_available: true, abstract: "Los Angeles, 1928. Christine Collins, mère célibataire et opératrice téléphonique, laisse à la maison son fils de neuf ans, Walter pour aller travailler. Le soir, quand elle rentre, elle retrouve la maison vide. Après l'enlèvement de son fils, elle est confrontée à la corruption des autorités de la ville.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "La Chambre verte", length_in_mn: 94, year: 1978, is_recorded: true, is_seen: false, is_available: true, abstract: "La femme de Gérard Mazet vient de décéder. Julien Davenne est arrivé dans l'est de la France pour le réconforter, mais lui-même vit un véritable drame : il est veuf, vit avec une gouvernante et Georges, un enfant sourd et muet à qui il apprend à parler. Dans cette même maison, où il abrite sa solitude, il a aménagé une chambre entièrement consacrée au souvenir de sa femme Julie. Au journal Le Globe, où il est rédacteur, il s'occupe de la rubrique nécrologique. Dans une vente, il rencontre Cécilia et leurs rapports évoluent en fonction de leur amour pour les morts.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Dressmaker", french_title: "Haute Couture", length_in_mn: 118, year: 2015, is_recorded: true, is_seen: false, is_available: true, abstract: "Dans les années 1950, Tilly Dunnage retourne, après 20 ans d'absence, dans son Australie d'origine pour s’occuper de sa mère Molly, seule et demi-folle. Avec sa machine à coudre et son apparence ""Haute-couture"", cette styliste va transformer les femmes de son petit village en vamps irrésistibles mais aspire avant tout à se venger de tous ceux qui l'ont bannie lorsqu'elle était enfant. Sans père, méprisée, elle était persécutée par les autres enfants et martyrisée par son institutrice. Souffre-douleur du fils du plus gros notable, elle sera accusée de l'avoir tué sur le faux témoignage de l'institutrice et envoyée loin de sa mère. Dans sa quête de la vérité elle sera aidée par le fils d'une famille de romanichels, un étrange chef de la police et sa mère soucieuse de réparer le passé.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Enquête sur les prédateurs terrestres", length_in_mn: 47, year: nil, is_recorded: true, is_seen: true, is_available: false, abstract: "Avant que l'homme ne domine le monde, la Terre était peuplée d'animaux géants. Parmi tous les prédateurs terrestres qui la peuplaient pendant la période Jurassique, cinq étaient particulièrement grands. Le phorusrhacidae, surnommé «oiseau-terreur», avait un profil similaire à l'autruche. Doté d'un gros bec, il chassait notamment des chevaux. Le smilodon, ou tigre à dents de sabre, et le megalania, une version surpuissante du dragon de Komodo, figuraient également parmi les principaux prédateurs de la préhistoire. Le deinosuchus, un crocodile de 10 mètres de long, capable de manger des dinosaures, et le légendaire T-Rex dominaient la chaîne alimentaire.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Mission Hannibal", length_in_mn: 52, year: nil, is_recorded: true, is_seen: false, is_available: true, abstract: "Hannibal était l'un des généraux les plus célèbres de l'histoire antique. Il est connu pour avoir traversé les Alpes au début de l'hiver, en 218 avant J.-C., afin de gagner le nord de l'Italie avec ses fantassins, ses cavaliers et ses éléphants. Un périple sans cesse discuté. Pourtant, grâce à des indices archéologiques, géologiques et historiques, une équipe d'experts internationaux tente de prouver qu'Hannnibal a bien réussi cet exploit.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Natural World - Les supercolonies de fourmis", length_in_mn: 55, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Dans le Jura suisse, une gigantesque colonie de fourmis, qui contient des millions d'ouvrières et des centaines de reine, prospère grâce à la coopération et l'entraide.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Pilot Guides - Le Japon", length_in_mn: 21, year: 2012, is_recorded: true, is_seen: false, is_available: true, abstract: "Megan McCormick arpente le Japon de Kyoto à Osaka, en passant par Sekigahara et Himeji, pour une plongée dans les lieux les plus intriguants de la culture et des traditions japonaises.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Tamara Vol.2", length_in_mn: 102, year: 2018, is_recorded: true, is_seen: true, is_available: false, abstract: "Séparée de Diego depuis deux ans, Tamara part s'installer à Paris pour débuter ses études. Contrainte à la colocation avec Wagner, elle y retrouve son ex-amoureux avec sa nouvelle copine...", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "I Give It a Year", french_title: "Mariage à l'anglaise", length_in_mn: 97, year: 2013, is_recorded: true, is_seen: true, is_available: false, abstract: "Nat et Josh, respectivement cadre ambitieuse et écrivain têtu, sont prêts à tout pour prouver à leurs proches que leur mariage peut durer plus d'une année. La solidité de leur union résistera-t-elle aux avances de Guy, un nouveau client de Nat, et de Chloé, l'ex copine de Josh ?", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Six Days Seven Nights", french_title: "6 jours, 7 nuits", length_in_mn: 98, year: 1998, is_recorded: true, is_seen: true, is_available: false, abstract: "À l'origine, cela devait être des vacances de rêves pour Robin Monrœ, rédactrice adjointe d'un grand magazine de mode new-yorkais et son fiancé le richissime et romantique Frank Martin. Contrainte d'abandonner celui-ci pour son travail en se rendant à Tahiti, Robin est amenée en coucou par le pilote baroudeur et bougon Quinn Harris mais leur avion s'écrase sur une île déserte. Robin et Quinn vont devoir apprendre à survivre ensemble pour s'en sortir, pourchassés par des pirates dans une jungle hostile. Pendant ce temps, Frank Martin tombe sous le charme d'une ancienne petite amie de Quinn...", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Le saut du diable", length_in_mn: 100, year: 2021, is_recorded: true, is_seen: true, is_available: false, abstract: "Paul Vilar est un ancien officier des forces spéciales et un spécialiste des sports extrêmes. Il est séparé de sa femme et tente de se rapprocher de sa fille de 17 ans lors d’une rando. Le problème c’est que Sara se retrouve témoin d’un meurtre. Des passeurs sont déterminés à prendre en chasse Paul et Sara pour les éliminer. Il va tout faire pour protéger sa fille en échappant aux tueurs à leurs trousses. Ces épreuves vont-elles permettre un rapprochement entre Paul et sa fille ?", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 3", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Silence and Suffering", french_title: "Silence et souffrance", length_in_mn: 55, year: 2016, is_recorded: true, is_seen: false, is_available: true, abstract: "Paul Spector, grièvement blessé par balles, a été laissé agonisant dans les bras de Stella Gibson. Mais le tueur en série, immédiatement pris en charge par les urgences, a miraculeusement survécu à ses blessures. L'homme et son ennemie, le super intendant Gibson, reprennent leur jeu du chat et de la souris : l'affrontement final approche...", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "His Troubled Thoughts", french_title: "Mémoire trouble", length_in_mn: 55, year: 2016, is_recorded: true, is_seen: false, is_available: true, abstract: "Stella est interrogée par l'Inspection Générale, qui lui fait des reproches quant à sa gestion du dossier. Spector se réveille mais il a perdu la mémoire. Sally décide de lui prendre un avocat. Elle emmène ensuite Olivia le voir à l'hôpital...", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Gates of Light", french_title: "Les Portes de la lumière", length_in_mn: 55, year: 2016, is_recorded: true, is_seen: false, is_available: true, abstract: "Après la découverte des cahiers de Spector, Stella se demande si les femmes dont il parle au fil de ces pages ne sont pas en réalité les descriptions d'autres meurtres. Le docteur Spencer apprend à Stella que Spector est conscient, mais qu'il semble avoir perdu la mémoire...", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "The Hell Within Him", french_title: "Le Poids du doute", length_in_mn: 55, year: 2016, is_recorded: false, is_seen: false, is_available: true, abstract: "Stella continue d'analyser ses rêves dans lesquels Paul Spector tente de la tuer. Les deux avocats chargés d'assurer la défense de Spector mettent en doute les techniques d'interrogatoires de Stella. Pendant ce temps, la femme de Paul a un geste désespéré...", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Wounds of Deadly Hate", french_title: "Les blessures d'une haine mortelle", length_in_mn: 55, year: 2016, is_recorded: false, is_seen: false, is_available: true, abstract: "Les enquêteurs se rendent en prison pour interroger David Alvarez, qui purge une peine à perpétuité pour le meurtre de Susan Harper. David était un ancien camarade de Spector à l'orphelinat, un lieu où ils ont tous deux souffert de sévices sexuels. Tente-t-il de couvrir un meurtre de Paul ?", rank: 5, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Their Solitary Way", french_title: "Leur chemin solitaire", length_in_mn: 55, year: 2016, is_recorded: false, is_seen: false, is_available: true, abstract: "Spector est interrogé au sujet de la mort de Susan Harper. Gibson affronte Paul et révèle ses failles au grand jour. Ce dernier réagit avec violence. A la clinique psychiatrique, le docteur Walden est persuadé que Spector simule son amnésie...", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "L’amica geniale", french_title: "L'amie prodigieuse", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "La série, fidèle à la saga des romans napolitains de Ferrante, narre l'histoire de l'amitié qui se poursuit tout au long de leur vie adulte entre deux petites filles qui grandissent dans un quartier pauvre et violent de Naples dans les années 1950, où commérages vont bon train et où la mafia règne.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 1", length_in_mn: nil, year: 2018, is_recorded: false, is_seen: false, is_available: true, abstract: "Quand la plus vieille amie d’Elena Greco semble avoir disparu sans laisser de trace, cette femme férue de littérature décide d’écrire l’histoire de leur amitié. Sa rencontre avec Raffaella Cerullo, qu’elle a toujours surnommée Lila, remonte à leur première année d’école primaire en 1950. Une amitié de plus de 60 ans, avec pour toile de fond la dangereuse et fascinante ville de Naples, que le destin et les décennies tenteront de mettre à mal, alors que les deux amies finiront par prendre des chemins différents dans la vie.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 2", length_in_mn: nil, year: 2020, is_recorded: false, is_seen: false, is_available: true, abstract: "Lila et Elena ont désormais seize ans. Si Lila se conforme tant bien que mal à son rôle d'épouse, Elena découvre une nouvelle ville et ...une autre vie possible. Dans ce nouveau chapitre, fidèlement adapté du tome 2 de la saga romanesque d'Elena Ferrante, les relations se tendent et les rivalités s'aiguisent entre les deux jeunes napolitaines au caractère bien trempé.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Le bambole", french_title: "Les Poupées", length_in_mn: 58, year: nil, is_recorded: true, is_seen: false, is_available: true, abstract: "Elena Greco reçoit un coup de fil annonçant la disparition de son amie d’enfance Lila. Depuis leur plus tendre enfance, les deux femmes ont créé un lien d’amitié indéfectible. Elena, désormais sexagénaire, décide de raconter l’histoire de leur vie. Celle-ci se déroule dans un quartier pauvre de la ville de Naples de la fin des années 1950. Lila Cerullo est une petite fille très intelligente mais rebelle. Par sa différence, elle est rejetée par ses camarades. Un jour, en classe, elle démontre des capacités exceptionnelles : elle a appris à lire et écrire seule. Intriguée par sa personnalité et ses connaissances, Elena, à partir de ce jour, se met en tête de devenir son amie coûte que coûte. Un jour, pour tester Elena, Lila décide de lui jeter sa poupée par les grilles de la cave du plus redouté de tous les habitants du quartier, vu comme un ogre : le mafieux Don Achille. En réponse et afin de s’affirmer, Elena en fait de même. Après être descendue toutes les deux dans la cave, et avoir tenté en vain de les récupérer, Lila imagine alors un plan : elles décident d’affronter Don Achille. Elles l’accusent d’avoir volé leurs poupées. Cette imagination tout droit venue de la bouillonnante Lila, portera ses fruits: en effet, admirant son courage, Don Achille finit par leur donner un billet pour qu’elles aillent se racheter une poupée chacune.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "I soldi", french_title: "L'Argent", length_in_mn: 58, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Avec l'argent du mafieux Don Achille, Elena et Lila achètent un livre : ""Les Quatre Filles du docteur March"". Lila imagine alors un plan : apprendre à écrire et faire un roman pour devenir riche comme Louisa May Alcott. Leur éducation vient à peine de commencer et elles obtiennent de très bonnes notes. Mme Oliveiro, leur institutrice, souhaite les voir passer le concours d’entrée au collège. Cependant, leur destinée reste prégnante. Les deux fillettes se voient très vite confrontées à la réalité de leur temps et de leur quartier. Dans la famille d'Elena, le père convainc sa femme, après de multiples négociations, de laisser leur fille étudier à condition qu’elle soit la meilleure de tout le quartier. Dans la famille Cerullo, les parents de Lila ne sont pas aussi compréhensifs. Ce n'est pas tant une question d'impossibilité financière, mais de l'entêtement. En réalité le père de Lila refuse d'en faire une possibilité : envoyer Lila au collège reviendrait à admettre que son propre enfant pourrait être plus intelligent, meilleur que lui. Ce sera le point de départ des 2 chemins divergents entre les deux filles. Leur monde devient étrangement plus petit et elles commencent à s'éloigner l'une de l'autre. Le quartier est alors secoué par le meurtre de Don Achille. Alfredo Peluso, ancien menuisier devenu un peu paranoïaque, sera accusé du crime et emmené en prison par les carabiniers. Même si Lila explique les détails de l'affaire à Elena, ceci semble bien sorti de son imagination et montre, encore une fois, une occasion de mettre en avant son imagination débordante. Elena finit par devenir l'auteur de sa propre fiction.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Le metamorfosi", french_title: "Les Métamorphoses", length_in_mn: 58, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Pour les filles la vie d'adolescent est une compétition plein de sous-entendus. Elena commence le collège. Pour Lila, ce fait est exaspérant : non seulement son amie la plus chère fréquente le collège qu'elle voulait tant, mais elle fait aussi un bond en avant vers la féminité. Quand Lila reste encore prépubère, le corps d'Elena a pris de l'avance sur celui de Lila : ses seins poussent et elle vient d'avoir ses règles. Chaque fille mène sa propre lutte intérieure pour savoir quelle est sa place dans la foule. Leur amitié subsiste même si une rivalité croissante naît entre elles. Lila passe tout son temps enfermée dans le magasin de son père, où elle travaille avec Carmela. Madame Oliveiro, avec ingérence, convainc les Greco d'envoyer Elena au lycée. Elena découvre peu à peu que son amie lui cache la vérité. Elle continue d’étudier en secret en empruntant des livres à la bibliothèque. Elle étudie le latin secret, et bien sûr elle le maîtrise avec une facilité déconcertante. Dans le quartier, depuis la mort de Don Achille, Marcello et Michele Solara de par la stature de leurs parents, continuent d’imposer encore un peu plus leur loi. Ils n’hésitant pas à humilier les moins aisés, comme Ada et Antonio. Au fur et à mesure, le dégoût de Lila pour Les Solara est de plus en plus apparent. Lorsque qu'ils arrachent le bracelet d'Elena de son poignet, la colère de Lila prend de l'ampleur : sa menace de trancher la gorge de Marcello s'il les touche à nouveau ne sera pas prise à la légère.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "La smarginatura", french_title: "La Délimitation", length_in_mn: 58, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Les années 1950 n'ont pas vraiment été l'âge des lumières de l'égalité des sexes. Tous les hommes qui croise le chemin d'Elena disent d'elle qu'elle est jolie, mais pas intelligente ou intéressante. Son statut semble n'être que ""décoratif"" ! Malgré tout, Lila et Elena passent le cap de l'adolescence et glissent vers la féminité. Les parents d'Elena ayant accepté qu’elle continue ses études au lycée, sont tout de même fiers d'elle. La jalousie de Lila se fait une nouvelle fois sentir. Elle trouve encore un moyen de devancer son amie : cette fois en apprenant le grec. Dans la cordonnerie de son père, elle travaille désormais sur une nouvelle paire de chaussures pour homme avec son frère Rino. Elle démontre ainsi de ses qualités créatives et par ce projet cherche à s'enrichir et à quitter le quartier. Lors d'une soirée organisée chez la mère de Gigliola, la tension avec les Solara est à son comble. Ils forcent Pasquale et Antonio à quitter la soirée : Marcello voulant Lila pour lui tout seul. Il en sera de même lors du réveillon du Nouvel An. Il se déroule sous le signe d’une bataille de feux d'artifice enflammés à la testostérone qui se termine par des coups de feu. Une véritable déclaration de guerre entre les deux clans du quartier. La politique est bien présente dans cet épisode. Le pays souhaite favoriser un boom économique, y compris Naples pourtant largement exclu. Des voyous comme les Solara, en ont profité et se sont enrichit grâce aux produits du marché noir. Leurs ennemis sont les communistes. Elena est perplexe sur l'opportunité de poursuivre Nino Sarratore, le fils du poète. Elle l'a connu à l'école primaire, lui avait demandé d'être sa petite amie et a ensuite déménagé avec sa famille déshonorée. Il est réapparu dans sa vie en un bel adolescent.", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Le scarpe", french_title: "Les Chaussures", length_in_mn: 58, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Lila reçoit des ""déclarations d'amour"" aussi différentes qu'impossible. Éperdument épris de Lila, Marcello se rapproche de son père afin de demander sa main. Elle le déteste et sait que sa proposition est aussi un pot-de-vin, avec la promesse d'une ""bague aux trois diamants"" et la perspective d'une vie de confort et d'aisance. Marcello suppose que Lila dira oui parce qu'aucune femme ne pourrait dire non. Il prend son refus comme une invitation à continuer. Pasquale est un maçon et un communiste ardent. Un avenir avec lui ressemblerait de façon frappante à la vie de ses parents. L'argent serait rare. Elle ne l'aime pas. Quant à Elena, elle qui sortait avec Gino prend la décision de le quitter. Elle effectue des brillantes études au collège. Cependant même si le monde d'Elena s'ouvre autour elle, cet épisode est toujours basé sur les querelles locales toujours fatigantes et insignifiantes pour elle. Lila néglige son travail à la cordonnerie, ce qui provoque des tensions. Il est furieux que Lila ait osé s'opposer à lui, et maintenant il est terrifié à l'idée que Rino, qui est censé travailler dans l'ombre de son père pendant des décennies, puisse apprendre le métier et ensuite poursuivre l'entreprise familiale en réussissant par lui-même. Pourtant Lila et son frère Rino ont conçu une paire de chaussures très originales. Leur père n'a pas l'intention de les laisser commercialiser ce nouveau produit. L'intellect de Lila a été une malédiction pour elle. Elle est assez brillante pour savoir qu'elle pourrait réussir sa vie, si seulement elle en avait l'occasion. Sans la promesse des chaussures, elle n'a pas de voie de sortie de sa condition dans ce quartier !", rank: 5, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "L'Isola", french_title: "L'Île", length_in_mn: 58, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Madame Oliveiro convainc Elena de se reposer de ses études en allant s'aérer sur l'île d'Ischia pendant les vacances d'été. Dans les années 50, pour une fille issue de cette catégorie sociale, c'est l'indépendance, l'éloignement des halls sordides de son immeuble et des querelles de voisinage, de la présence imminente de sa mère et surtout, du magnétisme de Lila. Elle est engagée comme femme de chambre dans une petite pension de famille. Pendant cette période estivale, elle sera seule, seule avec son grand amour : la mer. Nella, la gérante, lui demande de poser son stylo et d'enfiler son maillot de bain. Elena s'aventure sur le sable et se met à nager, comme sa mère lui avait assuré qu'elle le pouvait. Malgré tout, elle continue, inlassablement, à écrire à Lila. D'abord de longues lettres ""écrites"", pleines de gaieté qui ne font qu'inciter la jalousie de Lila et l'énerver. Lila ne répondra jamais, mettant Elena dans la position d'une adolescente désespérément sous l'emprise d'un ami qui ne pense à elle que par intermittence. La gérante lui apprend que la famille de Nino Sarratore doit venir passer quelques jours dans sa maison familiale. Elle est secrètement amoureuse de Nino. Pas nécessairement réciproque. Elle est aussi admirative de ce garçon intelligent. Elle pourrait tranquillement l'adorer. Cependant Nino est cassant. Il peut lui rappeler que les pauvres filles de l'arrière-pays de Naples n'obtiennent pas de " "promotions sociales"" et doivent rester dans leur condition miséreuse. Donato est le père de Nino. Il est différent de tous les hommes qu'elle connait. C'est est un intellectuel et un romantique. Il est attentif, lui disant combien il est fier d'elle pour avoir poursuivi sa scolarité. Il n'est pas surprenant qu'elle l'admire. Lorsque Lila la contacte pour lui confier la pression qu'elle subit de ses parents qui désirent la fiancer à Marcello Solara, elle décide de rentrer à Naples le lendemain. Mais le jour de son anniversaire, après le diner avec la famille Sarratore, elle part se coucher. Donato rendant visite à Elena sur son lit, la borde gentiment, éteint sa lumière, ferme doucement son livre, et quand un geste paternel sur Elena est attendu, le contraire se passe et se transforme en tragédie.", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "I fidanzati", french_title: "Les Fiancés", length_in_mn: 58, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "De retour à Naples, Elena espère confier à Lila la douloureuse expérience de ses vacances d'été. Sa vie, ses émotions tournent autour de Lila, mais aussi de ses propres batailles familiales, ses enchevêtrements romantiques, sa nature provocante, son intellect inexploité. Mais elle découvre que son amie s'est engagée à épouser Stefano Carracci en opposition aux avances de Marcello Solara. Stefano fait tout ce qui est en son pouvoir pour le surpasser. Marcello a pensé aux chaussures Cerullo, alors Stefano finance la transformation de leur magasin en un site de fabrication à part entière où ils peuvent concevoir, construire et vendre leurs propres chaussures. Lila s'engage à épouser Stefano ce qui la rendra riche - ce que Lila a voulu, avec intensité, depuis sa plus tendre enfance. En outre, le jeune homme signe un partenariat avec Don Fernando afin de développer la cordonnerie et la nouvelle ligne de chaussures Cerullo. Pour Marcello, en apprenant la nouvelle, l'orgueil est primordial. Il entre dans une colère noire et fomente un plan pour se venger de Lila. Lorsqu'elle revient en ville après ses fiançailles, elle doit rappeler à tout le quartier que sa vie antérieure de fille de cordonnier salie est révolue. Elle se promène en ville en décapotable tendance et luxueuse, avec une bague de perle au doigt et des lunettes de soleil sexy. Elena, elle, est en train de régler sa propre confusion romantique. Elle doit faire face à l'ajout de lunettes ""disgracieux"" sur son joli et doux visage. Elena, incapable de confier sa douloureuse expérience à son amie, se fiance à Antonio, qu'elle n'aime pas vraiment…", rank: 7, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "La promessa", french_title: "La Promesse", length_in_mn: 58, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Alors que le mariage de Lila se rapproche, la disparité entre les directions que prennent les vies de Lila et d'Elena s'accentue. Lila est prisonnière des exigences de sa famille, sur son rôle dans l'épicerie, sa robe de mariée, et son attitude. Elle est sous le charme de Stefano. Elle est l'objet de la jalousie de tout le quartier. Autrefois négligée et bafouée par son père pour ses aspirations intellectuelles, elle a aujourd'hui une influence sur le succès du magasin Cerullo. Elena, en revanche, n'est encore qu'une simple élève, qui doit faire face à l'ennui de l'autorité de son professeur et de sa mère. Elena se rend compte qu'elle n'est pas amoureuse d'Antonio. Leur relation n'est qu'une imposture. Elle veut rompre leurs fiançailles. Elle se rapproche de Nino Sarratore qui lui propose d'écrire des articles pour le journal du lycée. Au lieu de diviser les filles, ces différences les unissent dans une compréhension silencieuse. Plan sur la dévotion des deux amies l'une envers l'autre. « Tu es mon amie prodigieuse », déclare Lila en faisant promettre à Elena qu'elle ira à l'université. Lila est prête à payer les frais de scolarité d'Elena. Lila est suffisamment intelligente pour savoir ce dont elle manque, et visiblement peinée de savoir que les chances d'Elena d'être reconnue en tant qu'écrivain augmentent alors que les siennes ont disparu. Les préparatifs du mariage de Lila engendrent des tensions. L'événement est en passe d'être annulé. Elena parvient à calmer la situation. Les chaussures Cerullo ne se vendent pas, ce qui contraint Stefano à demander de l'aide aux Solara. La cérémonie de mariage arrive enfin, une journée joyeuse pour Lila et Stefano et pour les invités, dont la plupart ne dîneront ou ne s'habilleront peut-être jamais aussi bien pour le reste de leur vie. Au cours de celle-ci, Lila fait une découverte sur un arrangement machiavélique entre Stefano et les Solara se sentant piégée de l'intérieur !", rank: 8, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Crime à...", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "''", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Crime en Aveyron", length_in_mn: 90, year: 2014, is_recorded: true, is_seen: false, is_available: true, abstract: "Un homme est assassiné à Laguiole, en Aveyron, pays de l'Aubrac. La jeune Élisabeth Richard, substitut du procureur de Rodez, est chargée de l'affaire. Elle doit composer avec l'hostilité a priori du capitaine de gendarmerie Paul Jansac, promu à la force du poignet et pas enthousiaste à l'idée d'être subordonné à une femme. Élisabeth doit surtout démêler les imbroglios d'antagonismes ancestraux et percer les lourds secrets de familles pour démasquer le coupable.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Crime en Lozère", length_in_mn: 90, year: 2014, is_recorded: true, is_seen: false, is_available: true, abstract: "Dans le gouffre de l'aven Armand, en Lozère, on découvre le corps poignardé en plein cœur de Jérôme Sennac, exploitant agricole et guide bénévole. La vice-procureure de la République Élisabeth Richard et Paul Jansac, promu commandant de gendarmerie, se rendent sur les lieux pour mener l'enquête.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Crime à Aigues-Mortes", length_in_mn: 90, year: 2015, is_recorded: true, is_seen: false, is_available: true, abstract: "La procureure adjointe Elisabeth Richard et le chef de la police Paul Jansac font à nouveau équipe pour résoudre les meurtres consécutifs d'un jeune avocat et d'un agent immobilier à Aigues-Mortes, qui se sont tous deux soupçonnés d'un viol non résolu deux ans auparavant.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Crime à Martigues", length_in_mn: 90, year: 2016, is_recorded: true, is_seen: false, is_available: true, abstract: "Élisabeth Richard, procureure adjointe et Paul Jansac, capitaine de gendarmerie, sont chargés de l'enquête sur la mort de Pierre Saint-Florent dont le cadavre a été retrouvé sur une plage près de Martigues", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Crime dans les Alpilles", length_in_mn: 90, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "A Maussane-les-Alpilles, au cœur de la Provence, avec ses oliviers et ses charmantes places. La procureure adjointe Elisabeth Richard et le commandant de la gendarmerie locale Paul Jansac enquêtent sur le meurtre de Caroline Autiero, épouse d'un ancien propriétaire de moulin.", rank: 5, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Crime dans le Luberon", length_in_mn: 90, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Dans le Luberon, lors d'une chasse, Pascal Achard, un chasseur de 40 ans, est assassiné. La procureure adjointe Élisabeth Richard enquête pour la première fois avec le capitaine de gendarmerie Charles Jouanic, accompagné de son adjointe Caroline Martinez. Qui a tiré sur cet homme ? Et pourquoi ? En fouillant dans sa vie privée, les enquêteurs découvrent le profil sombre d'un séducteur et d'un manipulateur alors que leur enquête révèle de vieux secrets de famille.", rank: 6, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Crime dans l'Hérault", length_in_mn: 90, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "La patronne d'une discothèque du Cap d'Agde est retrouvée assassinée dans son propre bureau. Élisabeth Richard et Charles Jouanic se réunissent pour enquêter sur ce qui ressemble à un crime avec un motif évident, puisque le coffre-fort a été vidé de son argent.", rank: 7, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Crime dans le Larzac (Crime à Saint-Affrique)", length_in_mn: 90, year: 2020, is_recorded: true, is_seen: false, is_available: true, abstract: "Pierre Loiseau un éleveur et grand propriétaire de Saint-Affrique a été assassiné. De nombreux suspects sont au rendez vous pour la police : la petite amie, l’ex femme, un petit paysan ruiné du coin, un groupe d’antispécistes … Le lieutenant Caroline Martinez, le capitaine Charles Jouanic et la procureure Élisabeth Richard vont devoir infiltrer la commune de l’Aveyron afin de tenter de trouver la vérité.", rank: 8, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Crime à Biot", length_in_mn: 90, year: 2021, is_recorded: false, is_seen: false, is_available: true, abstract: "0", rank: 9, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Lucifer", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "Lassé et fatigué d'être le « Seigneur des Enfers », Lucifer Morningstar abandonne son royaume et s'en va à Los Angeles où il est propriétaire d'une boîte de nuit appelée « Le Lux ». Lucifer a reçu le don de contraindre les gens à révéler leurs désirs les plus profonds. Un soir, Lucifer assiste au meurtre d'une chanteuse pop devant son club. Il décide donc d'aller à la recherche du coupable et croise sur son chemin une policière nommée Chloe Decker qui résiste à son don et lui met des bâtons dans les roues. Pendant que Lucifer Morningstar et Chloé Decker font équipe pour trouver le meurtrier, Dieu envoie l'ange Amenadiel sur Terre pour convaincre Lucifer de revenir régner à nouveau sur l'Enfer.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Saison 2", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "La « Mère de la Création », déesse, ex-femme de Dieu et mère de Lucifer et d'Amenadiel, a réussi à s'échapper des Enfers et investit le corps de l'avocate Charlotte Richards, qui vient d'être assassinée en prenant son identité sociale et professionnelle. Lucifer et Amenadiel décident de faire tout leur possible pour découvrir ce qu'elle complote et la renvoyer en Enfer.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Everything's Coming Up Lucifer", french_title: "Tout arrive Lucifer/Maman où t'es ?", length_in_mn: 58, year: 2016, is_recorded: true, is_seen: false, is_available: true, abstract: "Activement à la recherche de sa mère qu'il pense être descendue sur Terre pour le tuer, Lucifer étudie le meurtre de Jillian Taylor, une ""doublure lumière"" retrouvée sur un plateau de cinéma, ayant deux barres en métal plantées sur le front. L'enquête les amène vers une affaire de drogue. Amenadiel apprend que l'inspecteur Decker a un échantillon du sang de Lucifer et veut le détruire, mais il réalise qu'il perd la maîtrise de son pouvoir.", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Liar, Liar, Slutty Dress on Fire", french_title: "Nouveau corps pour une nouvelle vie", length_in_mn: 58, year: 2016, is_recorded: true, is_seen: false, is_available: true, abstract: "La mère de Lucifer a fini par trouver le corps de Charlotte Richards, une avocate qui venait d'être assassinée. Lucifer tente de cacher les traces de l’assassinat mais ils trouvent le corps d'un jeune homme. Doutant de son innocence, Lucifer charge Maze de la surveiller tandis qu'il enquête.", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Sin-Eater", french_title: "Le Purificateur", length_in_mn: 58, year: 2016, is_recorded: true, is_seen: false, is_available: true, abstract: "Lucifer et Chloe enquêtent après la diffusion sur les réseaux sociaux d'une vidéo d'un meurtre et réalisent rapidement qu'ils ont affaire à un tueur en série. Lucifer tente de cacher sa mère du reste du monde, spécialement d'Amenadiel qui a juré de la renvoyer en Enfer, et de Mazikeen qui la hait.", rank: 3, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Lady Parts", french_title: "Soirée filles", length_in_mn: 58, year: 2016, is_recorded: true, is_seen: false, is_available: true, abstract: "Lucifer et Chloe enquêtent sur le meurtre d'une jeune femme retrouvée morte en robe de soirée dans les bois. La victime avait le tampon d'une boite de nuit sur le poignet. Lucifer profite de l’occasion pour pousser Chloe à prendre une soirée pour se détendre et sortir du travail, mais lui aussi trouve toutes les raisons possibles pour ignorer le fait que sa mère est encore sur Terre.", rank: 4, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "High Life", french_title: "High Life", length_in_mn: 110, year: 2018, is_recorded: true, is_seen: true, is_available: false, abstract: "Un groupe de criminels condamnés à mort accepte de voir commuer leur peine pour devenir les cobayes d’une mission spatiale en dehors du système solaire. Une mission hors normes…", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Love", french_title: "Space Time : L'ultime Odyssée", length_in_mn: 84, year: 2011, is_recorded: true, is_seen: true, is_available: false, abstract: "L'astronaute Lee Miller arrive à bord de la station spatiale internationale inoccupée depuis longtemps. Peu après, il perd le contact avec la Terre. Il essaye alors de s'occuper pour ne pas sombrer dans la folie au fur et a mesure que les systèmes de survie tombent en panne. Il découvre alors le journal du Captain Lee Briggs datant de la guerre de Sécession.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Schönes neues Brot", french_title: "De la farine au four, quel pain ?", length_in_mn: 86, year: 2019, is_recorded: true, is_seen: false, is_available: true, abstract: "Le savoir-faire des artisans boulangers face aux expérimentations de l’agro-industrie : sur le marché du pain, deux modèles se font face. Entre tradition et innovation, quel pain mangerons-nous demain ?", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Jusqu'à ce que la mort nous unisse", length_in_mn: 95, year: 2018, is_recorded: true, is_seen: false, is_available: true, abstract: "Les habitants du petit village de Colmars-les-Alpes sont bouleversés après la découverte du corps sans vie d'un garde moniteur du parc du Mercantour. Contre l'avis de tous, Vincent Lapaz, guide de haute montagne, tente de convaincre l'adjudante Servane Breitenbach que son ami d'enfance a été assassiné...", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Rouge Sang", length_in_mn: 89, year: 2014, is_recorded: true, is_seen: false, is_available: true, abstract: "À Brest, le pied d'une jeune femme est retrouvé à proximité de la mer. Alma Schneider, policière fraîchement débarquée de Paris, est chargée de résoudre cette affaire délicate. Grâce au soutien de César Istria, médecin légiste et archéologue, elle parvient à déterminer le lieu où la victime aurait été enterrée. Mais le corps qu'ils exhument est celui d'un homme. La victime s'avère avoir été une transsexuelle prénommée Diana et une personnalité influente de son vivant. Alma et César conjuguent leurs compétences pour venir à bout de cette énigme, qui les entraîne progressivement dans les entrailles de la ville.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Ronde de nuit", length_in_mn: 90, year: 2020, is_recorded: true, is_seen: false, is_available: true, abstract: "Mila est flic. Elle est de retour à Marseille après des années d’absence. Elle est solitaire, blessée, toujours sur ses gardes. Elle cherche son père qu’elle n’a pas revu depuis quinze ans. Fouad est candidat à la mairie du 14ème arrondissement de la Cité Phocéenne. Il est brillant, charmeur, prêt à tout pour parvenir à ses fins. C’est un symbole de réussite, il fait la fierté de sa mère. Mila et Fouad Mansouri sont frères et sœurs. C’est leur seul point commun. En revenant dans sa ville d’origine, Mila découvre ce qu’il reste d’une famille ravagée par un secret, une famille désunie prête à tout pour sauvegarder les apparences. L’histoire de cette famille s’inscrit en parallèle d’une enquête qui va faire voler en éclat un douloureux secret. A travers leurs relations tumultueuses et les péripéties de l’enquête, Ronde de Nuit nous entraîne dans une sombre affaire de meurtres, en famille…", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Escape from New York", french_title: "New York 1997", length_in_mn: 99, year: 1981, is_recorded: true, is_seen: true, is_available: false, abstract: "En 1988, à la suite de l'explosion de la criminalité aux États-Unis, l'île de Manhattan, un des arrondissements de la ville de New York est transformée en une « île-prison », un pénitencier à ciel ouvert. En 1997, la criminalité continuant d'augmenter, Manhattan est constamment surveillée par les forces de police. Entourée par un haut mur de confinement, des mines ont été placées sur les ponts reliant l'île au continent, rendant toute fuite des criminels impossible. L'île est alors le cadre de l'aventure de Snake Plissken, un redoutable hors-la-loi chargé par les autorités de la ville de sauver en moins de vingt-quatre heures le président des États-Unis qui a été fait prisonnier sur l'île.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Premières vacances", length_in_mn: 102, year: 2018, is_recorded: true, is_seen: true, is_available: false, abstract: "Marion et Ben font connaissance sur Tinder. Malgré leurs caractères complètement opposés, ils se mettent ensemble et décident de partir en vacances à deux, malgré l'avis négatif de leurs familles. Les deux tourtereaux se rendront en Bulgarie, pays qui se situe à mi-chemin de leurs destinations de rêve respectives.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "They Live", french_title: "Invasion Los Angeles", length_in_mn: 90, year: 1988, is_recorded: true, is_seen: true, is_available: false, abstract: "John Nada parcourt les routes à la recherche d'un emploi comme ouvrier sur les chantiers. Embauché à Los Angeles, il fait la connaissance de Frank Armitage qui lui propose de venir loger dans son bidonville. John va y découvrir une paire de lunettes de soleil hors du commun. Celles-ci permettent de voir le monde tel qu'il est réellement, à savoir gouverné par des extraterrestres à l'apparence humaine et maintenant la population dans un état apathique au moyen d'une propagande subliminale omniprésente. Après avoir tué à l'arme à feu quelques extra-terrestres, il s'efforce de convaincre Frank de la réalité de cette invasion. Tous deux entrent ensuite en contact avec un groupe de rebelles organisés et décidés à éradiquer les envahisseurs.", rank: nil, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Friends", french_title: "Friends", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "Les péripéties de trois jeunes femmes et trois jeunes hommes new-yorkais liés par une profonde amitié. Entre amour, travail, famille, ils partagent leurs bonheurs et leurs soucis au Central Perk, leur café favori.", rank: nil, language_version_id: 1, medium_ids:[1] })
