Record.create!({ original_title: "Big Little Lies", french_title: "Big Little Lies", length_in_mn: nil, year: nil, is_recorded: false, is_seen: false, is_available: true, abstract: "Madeline MacKenzie (Reese Witherspoon) est une mère de famille à la vie apparemment parfaite. Elle rencontre le jour de la rentrée scolaire Jane Chapman (Shailene Woodley), la jeune mère célibataire d'un petit garçon prénommé Ziggy (Iain Armitage). Madeline lui fait rencontrer sa meilleure amie, Celeste Wright (Nicole Kidman), une ancienne avocate d'apparence fragile, et les trois femmes se lient d'amitié.", rank: nil, language_version_id: 1, medium_ids:[1] })
