Record.create!({ original_title: "Auf gute Nachbarschaft", french_title: "Règlements de compte", length_in_mn: nil, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Merk, un homme acariâtre, est assassiné pendant qu'il s'adonnait à sa passion : chercher des trésors avec son détecteur de métaux. Lukas, Nina et Kroisleitner enquêtent sur ce crime. Ils soupçonnent d'abord son voisin, Théo Winkler, qui a déjà frappé Merk par le passé", rank: 1, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "Mord auf Raten", french_title: "Poison en héritage", length_in_mn: nil, year: 2017, is_recorded: true, is_seen: false, is_available: true, abstract: "Reihard Schattner, riche industriel et récemment veuf, pense avoir été empoisonné et demande à la comtesse Schöenberg d'intervenir auprès de la police de Kitzbühel pour mener l'enquête. Les soupçons se portent sur plusieurs personnes : Mélanie Robinek, la jeune fiancée de Reinhard Schattner, Bruno Feildberg jeune associé de l'entreprise en conflit avec Schattner, et sa fille aînée Dominika en froid avec son père", rank: 2, language_version_id: 1, medium_ids:[1] })
Record.create!({ original_title: "", french_title: "Soupçons", length_in_mn: nil, year: 2019, is_recorded: false, is_seen: false, is_available: true, abstract: "Victoire, institutrice, revient habiter dans le village de son enfance avec son mari et ses deux enfants. Elle retrouve Florent son premier amour.", rank: nil, language_version_id: 1, medium_ids:[1] })
